// Throwaway check 3: native Gemini API (generateContent) with Gemma, plus 26B on the OpenAI endpoint.
const key = process.env.HOSTED_API_KEY || process.env.GEMINI_API_KEY;
const native = "https://generativelanguage.googleapis.com/v1beta/models";

async function gen(model, label, body) {
  const t0 = Date.now();
  const res = await fetch(`${native}/${model}:generateContent`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-goog-api-key": key },
    body: JSON.stringify(body),
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let out = text.slice(0, 300);
  try {
    const j = JSON.parse(text);
    const parts = j.candidates?.[0]?.content?.parts;
    if (parts)
      out = JSON.stringify({
        parts: parts.map((p) => ({ thought: p.thought, text: p.text?.slice(0, 160), functionCall: p.functionCall })),
        usage: j.usageMetadata,
      });
    else if (j.error) out = JSON.stringify(j.error.message);
  } catch {}
  console.log(`\n[native ${model} | ${label}] HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);
}

async function oai(model, label, body) {
  const t0 = Date.now();
  const res = await fetch("https://generativelanguage.googleapis.com/v1beta/openai/chat/completions", {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
    body: JSON.stringify({ model, ...body }),
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let out = text.slice(0, 300);
  try {
    const j = JSON.parse(text);
    const m = j.choices?.[0]?.message;
    if (m) out = JSON.stringify({ content: m.content?.slice(0, 160), usage: j.usage });
  } catch {}
  console.log(`\n[openai ${model} | ${label}] HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);
}

const user = { role: "user", parts: [{ text: "Ask one short interview question about JWT refresh tokens." }] };
const sys = { parts: [{ text: "You are a terse technical interviewer." }] };
const m31 = "gemma-4-31b-it";
const m26 = "gemma-4-26b-a4b-it";

await gen(m31, "system + user", { systemInstruction: sys, contents: [user] });
await gen(m31, "thinkingLevel minimal", { systemInstruction: sys, contents: [user], generationConfig: { thinkingConfig: { thinkingLevel: "minimal" } } });
await gen(m31, "thinkingBudget 0", { systemInstruction: sys, contents: [user], generationConfig: { thinkingConfig: { thinkingBudget: 0 } } });
await gen(m31, "json schema", {
  contents: [{ role: "user", parts: [{ text: 'Score the answer "I used JWT because it is stateless" from 0 to 4.' }] }],
  generationConfig: {
    responseMimeType: "application/json",
    responseSchema: { type: "OBJECT", properties: { score: { type: "INTEGER" }, reason: { type: "STRING" } }, required: ["score", "reason"] },
