});
await gen(m26, "system + user", { systemInstruction: sys, contents: [user] });
await oai(m26, "user only", { messages: [{ role: "user", content: "Ask one short interview question about JWT refresh tokens." }] });
await oai(m26, "system + user", {
  messages: [
    { role: "system", content: "You are a terse technical interviewer." },
    { role: "user", content: "Ask one short interview question about JWT refresh tokens." },
  ],
});

