// Throwaway check 4: native API with thinkingLevel "minimal": JSON schema, tool call, repeat latency.
const key = process.env.HOSTED_API_KEY || process.env.GEMINI_API_KEY;
const native = "https://generativelanguage.googleapis.com/v1beta/models";
const minimal = { thinkingConfig: { thinkingLevel: "minimal" } };
const sys = { parts: [{ text: "You are a terse technical interviewer." }] };

async function gen(model, label, body) {
  const t0 = Date.now();
  const res = await fetch(`${native}/${model}:generateContent`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-goog-api-key": key },
    body: JSON.stringify(body),
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let out = text.slice(0, 300);
  try {
    const j = JSON.parse(text);
    const parts = j.candidates?.[0]?.content?.parts;
    if (parts)
      out = JSON.stringify({
        parts: parts.filter((p) => !p.thought).map((p) => ({ text: p.text?.slice(0, 200), functionCall: p.functionCall })),
        thoughts: j.usageMetadata?.thoughtsTokenCount ?? 0,
        total: j.usageMetadata?.totalTokenCount,
      });
    else if (j.error) out = JSON.stringify(j.error.message);
  } catch {}
  console.log(`\n[${model} | ${label}] HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);
}

const scorePrompt = { role: "user", parts: [{ text: 'Score the answer "I used JWT because it is stateless" from 0 to 4.' }] };
const schema = {
  responseMimeType: "application/json",
  responseSchema: { type: "OBJECT", properties: { score: { type: "INTEGER" }, reason: { type: "STRING" } }, required: ["score", "reason"] },
};
const tools = [
  {
    functionDeclarations: [
      {
        name: "readFile",
        description: "Read a file from the candidate's repo",
        parameters: { type: "OBJECT", properties: { path: { type: "STRING" } }, required: ["path"] },
      },
    ],
  },
];
const toolPrompt = { role: "user", parts: [{ text: "Open src/auth.ts and ask me one question about it. Use the tool first." }] };

for (const model of ["gemma-4-31b-it", "gemma-4-26b-a4b-it"]) {
  await gen(model, "minimal + system + json schema", { systemInstruction: sys, contents: [scorePrompt], generationConfig: { ...minimal, ...schema } });
  await gen(model, "minimal + system + tool", { systemInstruction: sys, contents: [toolPrompt], tools, generationConfig: minimal });
  await gen(model, "minimal + system + plain (run 2)", {
    systemInstruction: sys,
    contents: [{ role: "user", parts: [{ text: "Ask one short interview question about database indexes." }] }],
    generationConfig: minimal,
  });
}

