/**
 * Phase 0.4 spike (throwaway): does Mastra memory on LibSQL work inside a Next.js route,
 * in `next dev` and in a production build? LibSQL is a native module, so a script alone
 * would not prove this.
 *
 *   POST /api/spike-memory   { "repoId": "...", "weakSpots": ["..."] }  -> saves
 *   GET  /api/spike-memory?repoId=...                                    -> reads back
 */
import path from "node:path";
import { mkdirSync } from "node:fs";
import { LibSQLStore } from "@mastra/libsql";
import { Memory } from "@mastra/memory";

// Absolute path: a relative "file:" URL resolves differently under Next.js than in a script.
const dbPath = path.resolve(process.cwd(), process.env.MEMORY_DB_PATH ?? ".viva/memory.db");
mkdirSync(path.dirname(dbPath), { recursive: true });

const memory = new Memory({
  storage: new LibSQLStore({ id: "viva-memory", url: `file:${dbPath}` }),
});

export async function POST(request: Request) {
  const { repoId, weakSpots } = (await request.json()) as { repoId: string; weakSpots: string[] };
  // One thread per repo; the weak spots travel in the thread's metadata.
  await memory.createThread({ threadId: repoId, resourceId: repoId, metadata: { weakSpots, savedAt: Date.now() } });
  return Response.json({ saved: true });
}

export async function GET(request: Request) {
  const repoId = new URL(request.url).searchParams.get("repoId") ?? "";
  const thread = await memory.getThreadById({ threadId: repoId });
  return Response.json({ found: thread !== null, metadata: thread?.metadata ?? null });
}

