import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    // fixtures/ holds snapshots of other repos (including their own test files); never run those.
    exclude: ["node_modules/**", ".next/**", "fixtures/**"],
  },
});

/**
 * Phase 0.7 model benchmark: the same two prompts on hosted Gemma and on local Gemma.
 *
 *   pnpm bench hosted 5     (needs HOSTED_API_KEY in .env)
 *   pnpm bench ollama 3     (needs Ollama running with OLLAMA_MODEL pulled)
 *
 * Measures, per prompt:
 *   - validity:  did the output parse against the zod schema?
 *   - real-file: do the file paths the model names exist in the repo? (it must not invent files)
 *   - latency:   wall-clock time per call
 *
 * The input is a small fixture so the local model can finish in reasonable time.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { Agent } from "@mastra/core/agent";
import { z } from "zod";

const provider = process.argv[2] === "ollama" ? "ollama" : "hosted";
const runs = Number(process.argv[3] ?? (provider === "hosted" ? 5 : 3));

const model =
  provider === "hosted"
    ? {
        id: `google/${process.env.HOSTED_MODEL ?? "gemma-4-26b-a4b-it"}` as const,
        apiKey: process.env.HOSTED_API_KEY,
      }
    : {
        id: `ollama/${process.env.OLLAMA_MODEL ?? "gemma4:e4b"}` as const,
        url: process.env.OLLAMA_BASE_URL ?? "http://localhost:11434/v1",
      };

// Hosted calls should answer in seconds; a silent hang is cut off. Local CPU inference needs minutes.
const CALL_TIMEOUT_MS = provider === "hosted" ? 30_000 : 900_000;
const providerOptions = { google: { thinkingConfig: { thinkingLevel: "minimal" as const } } };

// ---- fixture input -------------------------------------------------------------------------

const fixtureDir = path.resolve(process.cwd(), "fixtures/portfolio-new");

// FILES.tsv has one "<bytes>\t<path>" line per tracked file. Keep source paths only.
const filePaths = readFileSync(path.join(fixtureDir, "FILES.tsv"), "utf8")
  .split("\n")
  .map((line) => line.split("\t")[1]?.trim())
  .filter((p): p is string => Boolean(p))
  .filter((p) => !p.startsWith("public/") && !/\.(webp|png|jpg|lockb)$/.test(p) && p !== "package-lock.json");

const readme = readFileSync(path.join(fixtureDir, "files/README.md"), "utf8");
const packageJson = readFileSync(path.join(fixtureDir, "files/package.json"), "utf8");

const context = [
  "FILES IN THE REPO:",
  filePaths.join("\n"),
  "",
  "README.md:",
  readme,
  "",
  "package.json:",
  packageJson,
].join("\n");

// ---- the two prompts -----------------------------------------------------------------------

const Brief = z.object({
  summary: z.string().min(1),
  stack: z.array(z.string()).min(1),
  hooks: z.array(z.object({ file: z.string(), why: z.string() })).min(1),
});

const DeepDive = z.object({
  question: z.string().min(1),
  file: z.string(),
});

type Result = { valid: boolean; named: number; real: number; ms: number; error?: string };

const agent = new Agent({
  id: "bench",
  name: "Bench",
  instructions: "You are a technical interviewer preparing to question a student about their own project.",
  model,
});

async function runBrief(): Promise<Result> {
  const start = Date.now();
  const res = await agent.generate(
    `${context}\n\nWrite a project brief: a 2 sentence summary, the tech stack, and 3 interview hooks. ` +
      `Each hook must name one file path copied exactly from FILES IN THE REPO and say why it is worth asking about.`,
    {
      providerOptions,
      structuredOutput: { schema: Brief, jsonPromptInjection: true },
      abortSignal: AbortSignal.timeout(CALL_TIMEOUT_MS),
    },
  );
  const parsed = Brief.safeParse(res.object);
  const files = parsed.success ? parsed.data.hooks.map((h) => h.file) : [];
  return {
    valid: parsed.success,
    named: files.length,
    real: files.filter((f) => filePaths.includes(f)).length,
    ms: Date.now() - start,
  };
}

async function runQuestion(): Promise<Result> {
  const start = Date.now();
  const res = await agent.generate(
    `${context}\n\nAsk one deep-dive interview question about a design decision in this project. ` +
      `Name the one file it is about, copied exactly from FILES IN THE REPO.`,
    {
      providerOptions,
      structuredOutput: { schema: DeepDive, jsonPromptInjection: true },
      abortSignal: AbortSignal.timeout(CALL_TIMEOUT_MS),
    },
  );
  const parsed = DeepDive.safeParse(res.object);
  return {
    valid: parsed.success,
    named: parsed.success ? 1 : 0,
    real: parsed.success && filePaths.includes(parsed.data.file) ? 1 : 0,
    ms: Date.now() - start,
  };
}

// ---- runner --------------------------------------------------------------------------------

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

async function bench(name: string, run: () => Promise<Result>) {
  const results: Result[] = [];
  for (let i = 0; i < runs; i++) {
    const start = Date.now();
    try {
      results.push(await run());
    } catch (err) {
      const message = err instanceof Error ? err.message.slice(0, 120) : String(err);
      results.push({ valid: false, named: 0, real: 0, ms: Date.now() - start, error: message });
    }
  }
  const valid = results.filter((r) => r.valid).length;
  const named = results.reduce((sum, r) => sum + r.named, 0);
  const real = results.reduce((sum, r) => sum + r.real, 0);
  console.log(
    `${name}: valid ${valid}/${runs}, real files ${real}/${named} named, ` +
      `median ${median(results.map((r) => r.ms))} ms, runs [${results.map((r) => r.ms).join(", ")}] ms`,
  );
  for (const e of new Set(results.map((r) => r.error).filter(Boolean))) console.log(`  error: ${e}`);
}

async function main() {
  console.log(`provider=${provider} model=${model.id} runs=${runs} context=${context.length} chars, ${filePaths.length} files`);
  await bench("brief", runBrief);
  await bench("question", runQuestion);
}

main();

/**
 * The one place that decides which Gemma the app talks to.
 *
 * Every model call goes through getModelConfig(), so switching between the hosted model
 * and the local Ollama model is a single env variable (LLM_PROVIDER).
 */

export type Provider = "hosted" | "ollama";

export function getProvider(): Provider {
  return process.env.LLM_PROVIDER === "ollama" ? "ollama" : "hosted";
}

/** The model name without any provider prefix, for logs, reports and traces. */
export function getModelName(provider: Provider = getProvider()): string {
  return provider === "hosted"
    ? (process.env.HOSTED_MODEL ?? "gemma-4-26b-a4b-it")
    : (process.env.OLLAMA_MODEL ?? "gemma4:e4b");
}

/**
 * The model config in the shape Mastra's model router expects: "<provider>/<model>".
 *
 * - hosted, no HOSTED_BASE_URL: Google AI Studio through Google's native API.
 * - hosted, with HOSTED_BASE_URL: any OpenAI-compatible endpoint (the OpenRouter fallback).
 *   This path is documented but has not been run by us yet.
 * - ollama: Ollama's OpenAI-compatible endpoint on this machine.
 */
export function getModelConfig(provider: Provider = getProvider()) {
  const name = getModelName(provider);

  if (provider === "ollama") {
    return {
      id: `ollama/${name}` as const,
      url: process.env.OLLAMA_BASE_URL ?? "http://localhost:11434/v1",
    };
  }

  const baseUrl = process.env.HOSTED_BASE_URL?.trim();
  if (baseUrl) {
    return { id: `custom/${name}` as const, url: baseUrl, apiKey: process.env.HOSTED_API_KEY };
  }
  return { id: `google/${name}` as const, apiKey: process.env.HOSTED_API_KEY };
}

/**
 * Gemma 4 "thinks" before answering by default, which adds many seconds per call.
 * Minimal thinking keeps an interview turn fast. Only Google's API reads this option.
 */
export const providerOptions = {
  google: { thinkingConfig: { thinkingLevel: "minimal" as const } },
};

/**
 * How long one model call may take before we give up on it.
 * Hosted calls answer in seconds; without a limit a silent hang lasts 5 minutes
 * (Node's default fetch timeout). Local CPU inference really does need minutes.
 */
export function getCallTimeoutMs(provider: Provider = getProvider()): number {
  return provider === "hosted" ? 30_000 : 900_000;
}

/**
 * Structured output helper: ask Gemma for JSON, check it with zod, repair once, then fall back.
 *
 * Rule from CLAUDE.md: bad model output must never crash the UI. So this function never throws.
 * It always returns a value of the right type plus metadata saying how it got there.
 */
import { Agent } from "@mastra/core/agent";
import type { z } from "zod";
import { getCallTimeoutMs, getModelConfig, getModelName, getProvider, providerOptions } from "./provider";

export type StructuredMeta = {
  provider: string;
  model: string;
  /** Wall-clock time for all attempts together. */
  ms: number;
  /** True when the first reply was unusable and the second attempt was needed. */
  repaired: boolean;
  /** True when both attempts failed and the caller's fallback value was returned. */
  usedFallback: boolean;
  inputTokens?: number;
  outputTokens?: number;
  error?: string;
};

export type GenerateArgs = { instructions: string; prompt: string; schema: z.ZodType };
export type GenerateResult = { object: unknown; inputTokens?: number; outputTokens?: number };
/** The model call itself. Tests pass a fake one; the app uses mastraGenerate below. */
export type GenerateFn = (args: GenerateArgs) => Promise<GenerateResult>;

/** Real model call through a Mastra agent. */
export const mastraGenerate: GenerateFn = async ({ instructions, prompt, schema }) => {
  const agent = new Agent({ id: "viva-structured", name: "Viva", instructions, model: getModelConfig() });
  const res = await agent.generate(prompt, {
    providerOptions,
    // The schema is described in the prompt instead of using Google's JSON-schema mode,
    // which hung without answering in our Phase 0 tests (DECISIONS D25).
    structuredOutput: { schema, jsonPromptInjection: true },
    abortSignal: AbortSignal.timeout(getCallTimeoutMs()),
  });
  const usage = res.usage as { inputTokens?: number; outputTokens?: number } | undefined;
  return { object: res.object, inputTokens: usage?.inputTokens, outputTokens: usage?.outputTokens };
};

export async function generateStructured<T>(options: {
  instructions: string;
  prompt: string;
  schema: z.ZodType<T>;
  /** Returned when the model fails twice. Must be safe to show to the user. */
  fallback: T;
  generate?: GenerateFn;
}): Promise<{ value: T; meta: StructuredMeta }> {
  const { instructions, prompt, schema, fallback } = options;
  const generate = options.generate ?? mastraGenerate;
  const start = Date.now();
  const meta: StructuredMeta = {
    provider: getProvider(),
    model: getModelName(),
    ms: 0,
    repaired: false,
    usedFallback: false,
  };

  let lastError = "";
  for (const attempt of [1, 2]) {
    // On the second attempt, tell the model what was wrong with its first reply.
    const attemptPrompt =
      attempt === 1
        ? prompt
        : `${prompt}\n\nYour previous reply could not be used: ${lastError}\nReply again with only valid JSON that matches the schema.`;
    try {
      const res = await generate({ instructions, prompt: attemptPrompt, schema });
      meta.inputTokens = res.inputTokens;
      meta.outputTokens = res.outputTokens;
      const parsed = schema.safeParse(res.object);
      if (parsed.success) {
        meta.repaired = attempt === 2;
        meta.ms = Date.now() - start;
        return { value: parsed.data, meta };
      }
      lastError = parsed.error.issues
        .slice(0, 3)
        .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
        .join("; ");
    } catch (err) {
      lastError = err instanceof Error ? err.message.slice(0, 200) : String(err);
    }
  }

  meta.repaired = true;
  meta.usedFallback = true;
  meta.error = lastError;
  meta.ms = Date.now() - start;
  return { value: fallback, meta };
}

/** One file in the candidate's repo. */
export type RepoFile = { path: string; size: number };

/**
 * A repo Viva can read, wherever it comes from (GitHub, a local folder, or a test fixture).
 * `files` is the complete list of real paths; everything the model says is checked against it.
 */
export type RepoSource = {
  /** Stable id for this repo, used as the memory key (for example "github:owner/name"). */
  id: string;
  /** Human-readable name shown in the UI. */
  label: string;
  files: RepoFile[];
  /** Reads one file. Throws if the path is not in `files`. */
  readFile(path: string): Promise<string>;
};

/** A file chosen for the model to read, with the reason it was chosen. */
export type SelectedFile = RepoFile & { score: number; reason: string };

/** A file's text as given to the model (possibly cut to the per-file limit). */
export type FileContent = { path: string; content: string; truncated: boolean };

/**
 * File selection: pick the files that tell an interviewer the most about a project,
 * within a size budget the model can read quickly.
 *
 * Pure functions, no I/O, so the heuristic is easy to test and to explain.
 */
import type { FileContent, RepoFile, RepoSource, SelectedFile } from "./types";

/** Total characters of file content sent to the model for the brief (about 10k tokens). */
export const BRIEF_BUDGET_CHARS = 40_000;
/** No single file may use more than this, so one big file cannot crowd out the rest. */
export const PER_FILE_CAP_CHARS = 6_000;
/** Files larger than this are almost always generated or data, not hand-written code. */
const MAX_FILE_BYTES = 200_000;

const IGNORED_DIRS = [
  "node_modules", ".git", ".next", "dist", "build", "out", "coverage", "vendor",
  "__pycache__", ".venv", "venv", "target", ".idea", ".vscode", "public", "assets", "static",
];

const IGNORED_FILES = [
  "package-lock.json", "pnpm-lock.yaml", "yarn.lock", "bun.lockb", "poetry.lock", "Cargo.lock",
  "next-env.d.ts", ".gitignore", ".DS_Store",
];

const BINARY_EXTENSIONS = /\.(png|jpe?g|gif|webp|ico|svg|pdf|zip|gz|tar|woff2?|ttf|eot|mp3|mp4|mov|lockb|pyc|exe|dll|so|bin)$/i;
const CODE_EXTENSIONS = /\.(ts|tsx|js|jsx|mjs|py|go|rs|java|kt|rb|php|cs|c|cpp|h|swift|sql|prisma)$/i;

const MANIFESTS = ["package.json", "requirements.txt", "pyproject.toml", "go.mod", "Cargo.toml", "pom.xml", "build.gradle", "Gemfile"];
const ARCHITECTURE_FILES = ["docker-compose.yml", "docker-compose.yaml", "Dockerfile", "render.yaml", "schema.sql", "schema.prisma", ".env.example", "vercel.json", "netlify.toml"];
const ENTRY_POINTS = /^(app|main|index|server|manage|wsgi|asgi)\.(py|ts|tsx|js|jsx|go|rs)$|^App\.(tsx|jsx)$|^(page|layout|route)\.(tsx|ts)$/;

export function estimateTokens(chars: number): number {
  // Rough rule of thumb for English text and code: about 4 characters per token.
  return Math.ceil(chars / 4);
}

export function isIgnored(file: RepoFile): boolean {
  const parts = file.path.split("/");
  const name = parts[parts.length - 1];
  if (parts.slice(0, -1).some((dir) => IGNORED_DIRS.includes(dir))) return true;
  if (IGNORED_FILES.includes(name)) return true;
  if (BINARY_EXTENSIONS.test(name)) return true;
  if (/\.min\.(js|css)$/.test(name)) return true;
  if (file.size === 0 || file.size > MAX_FILE_BYTES) return true;
  return false;
}

/** Higher score = more useful to an interviewer. Returns the score and a short reason. */
export function scoreFile(file: RepoFile): { score: number; reason: string } {
  const parts = file.path.split("/");
  const name = parts[parts.length - 1];
  const depth = parts.length - 1;
  const isTest = /(^|\/)(tests?|__tests__|spec)\//.test(file.path) || /\.(test|spec)\.[a-z]+$/.test(name) || /^test_/.test(name);

  if (/^readme(\.md)?$/i.test(name) && depth === 0) return { score: 100, reason: "README" };
  if (MANIFESTS.includes(name)) return { score: 90 - depth, reason: "manifest (dependencies and scripts)" };
  if (ARCHITECTURE_FILES.includes(name)) return { score: 80 - depth, reason: "architecture config" };
  if (isTest) return { score: 10, reason: "test" };
  if (ENTRY_POINTS.test(name)) return { score: 70 - depth, reason: "entry point" };
  if (CODE_EXTENSIONS.test(name)) {
    // Central files tend to be larger and closer to the root.
    const sizeBonus = Math.min(file.size / 1000, 20);
    return { score: 40 + sizeBonus - depth * 2, reason: "source file" };
  }
  if (/\.(md|mdx|txt)$/i.test(name)) return { score: 15, reason: "documentation" };
  if (/\.(json|ya?ml|toml|ini|cfg)$/i.test(name)) return { score: 12, reason: "config" };
  return { score: 5, reason: "other" };
}

/**
 * Chooses files in score order until the budget is used up.
 * A file counts for at most `perFileCap` characters because that is all the model will see of it.
 */
export function selectFiles(
  files: RepoFile[],
  budgetChars: number = BRIEF_BUDGET_CHARS,
  perFileCap: number = PER_FILE_CAP_CHARS,
): SelectedFile[] {
  const ranked = files
    .filter((file) => !isIgnored(file))
    .map((file) => ({ ...file, ...scoreFile(file) }))
    .sort((a, b) => b.score - a.score || a.path.localeCompare(b.path));

  const selected: SelectedFile[] = [];
  let used = 0;
  for (const file of ranked) {
    const cost = Math.min(file.size, perFileCap);
    if (used + cost > budgetChars) continue;
    selected.push(file);
    used += cost;
  }
  return selected;
}

/** Reads the selected files, cutting each to the per-file limit. */
export async function loadContents(
  source: RepoSource,
  selected: RepoFile[],
  perFileCap: number = PER_FILE_CAP_CHARS,
): Promise<FileContent[]> {
  const contents: FileContent[] = [];
  for (const file of selected) {
    try {
      const text = await source.readFile(file.path);
      contents.push({ path: file.path, content: text.slice(0, perFileCap), truncated: text.length > perFileCap });
    } catch {
      // A file that cannot be read (deleted, binary, network error) is skipped, not fatal.
    }
  }
  return contents;
}

/** Reads a public GitHub repo through the REST API. Works without a token; GITHUB_TOKEN raises the rate limit. */
import type { RepoFile, RepoSource } from "./types";

export type GitHubRef = { owner: string; repo: string };

/** Accepts "https://github.com/owner/repo", with or without ".git" or a trailing path, and "owner/repo". */
export function parseGitHubUrl(input: string): GitHubRef | null {
  const trimmed = input.trim();
  const match =
    trimmed.match(/^https?:\/\/github\.com\/([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:[/?#].*)?$/i) ??
    trimmed.match(/^([\w.-]+)\/([\w.-]+)$/);
  if (!match) return null;
  return { owner: match[1], repo: match[2] };
}

async function githubJson<T>(path: string): Promise<T> {
  const headers: Record<string, string> = { accept: "application/vnd.github+json" };
  if (process.env.GITHUB_TOKEN) headers.authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  const res = await fetch(`https://api.github.com${path}`, { headers, signal: AbortSignal.timeout(20_000) });
  if (res.status === 404) throw new Error("Repository not found, or it is private.");
  if (res.status === 403 || res.status === 429) throw new Error("GitHub rate limit reached. Try again later or set GITHUB_TOKEN.");
  if (!res.ok) throw new Error(`GitHub API error ${res.status}.`);
  return (await res.json()) as T;
}

export async function loadGitHubRepo(url: string): Promise<RepoSource> {
  const ref = parseGitHubUrl(url);
  if (!ref) throw new Error("That does not look like a GitHub repository URL.");
  const { owner, repo } = ref;

  const info = await githubJson<{ default_branch: string }>(`/repos/${owner}/${repo}`);
  const branch = await githubJson<{ commit: { sha: string } }>(`/repos/${owner}/${repo}/branches/${info.default_branch}`);
  const sha = branch.commit.sha;
  const tree = await githubJson<{ tree: { path: string; type: string; size?: number }[] }>(
    `/repos/${owner}/${repo}/git/trees/${sha}?recursive=1`,
  );

  const files: RepoFile[] = tree.tree
    .filter((entry) => entry.type === "blob")
    .map((entry) => ({ path: entry.path, size: entry.size ?? 0 }));
  const known = new Set(files.map((file) => file.path));

  return {
    id: `github:${owner}/${repo}`.toLowerCase(),
    label: `${owner}/${repo}`,
    files,
    async readFile(path) {
      // Only paths from the real tree are fetched, so a model-invented path can never reach the network.
      if (!known.has(path)) throw new Error(`Not a file in this repo: ${path}`);
      const encoded = path.split("/").map(encodeURIComponent).join("/");
      const res = await fetch(`https://raw.githubusercontent.com/${owner}/${repo}/${sha}/${encoded}`, {
        signal: AbortSignal.timeout(20_000),
      });
      if (!res.ok) throw new Error(`Could not read ${path} (${res.status}).`);
      return res.text();
    },
  };
}

/** Reads a project from a folder on this machine. Only allowed when LOCAL_MODE=true. */
import { readdir, readFile, stat } from "node:fs/promises";
import path from "node:path";
import type { RepoFile, RepoSource } from "./types";

// Folders that are never worth walking into (huge, generated, or private).
const SKIP_DIRS = new Set(["node_modules", ".git", ".next", "dist", "build", "out", "coverage", ".venv", "venv", "__pycache__", "target", ".viva"]);
const MAX_FILES = 5_000;

async function walk(root: string, dir: string, files: RepoFile[]): Promise<void> {
  if (files.length >= MAX_FILES) return;
  for (const entry of await readdir(path.join(root, dir), { withFileTypes: true })) {
    const relative = dir ? `${dir}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name)) await walk(root, relative, files);
    } else if (entry.isFile()) {
      // .env files hold secrets; they are never listed, so they can never be sent to a model.
      if (/^\.env(\..*)?$/.test(entry.name) && !entry.name.endsWith(".example")) continue;
      const info = await stat(path.join(root, relative));
      files.push({ path: relative, size: info.size });
    }
  }
}

/** Reads fixtures in tests and evals without needing LOCAL_MODE. */
export async function loadFolder(folder: string, id: string, label: string): Promise<RepoSource> {
  const root = path.resolve(folder);
  const files: RepoFile[] = [];
  await walk(root, "", files);
  const known = new Set(files.map((file) => file.path));
  return {
    id,
    label,
    files,
    async readFile(filePath) {
      if (!known.has(filePath)) throw new Error(`Not a file in this project: ${filePath}`);
      return readFile(path.join(root, filePath), "utf8");
    },
  };
}

export async function loadLocalRepo(folder: string): Promise<RepoSource> {
  if (process.env.LOCAL_MODE !== "true") {
    throw new Error("Local folders can only be read in local mode (LOCAL_MODE=true).");
  }
  const root = path.resolve(folder);
  return loadFolder(root, `local:${root.replaceAll("\\", "/").toLowerCase()}`, path.basename(root));
}

/**
 * Reads a repo snapshot from fixtures/<name>/ (used by tests, evals and the offline demo).
 * FILES.tsv lists every file the real repo has; files/ holds the text files we snapshotted.
 */
import { readFile } from "node:fs/promises";
import { readFileSync } from "node:fs";
import path from "node:path";
import type { RepoFile, RepoSource } from "./types";

export const FIXTURE_NAMES = ["portfolio-new", "vidyut-mitra"] as const;
export type FixtureName = (typeof FIXTURE_NAMES)[number];

export function loadFixture(name: FixtureName, fixturesDir: string = path.resolve(process.cwd(), "fixtures")): RepoSource {
  const dir = path.join(fixturesDir, name);
  // Each line is "<size in bytes>\t<path>".
  const files: RepoFile[] = readFileSync(path.join(dir, "FILES.tsv"), "utf8")
    .split(/\r?\n/)
    .filter((line) => line.includes("\t"))
    .map((line) => {
      const [size, filePath] = line.split("\t");
      return { path: filePath.trim(), size: Number(size) };
    });
  const known = new Set(files.map((file) => file.path));

  return {
    id: `fixture:${name}`,
    label: name,
    files,
    async readFile(filePath) {
      if (!known.has(filePath)) throw new Error(`Not a file in this fixture: ${filePath}`);
      return readFile(path.join(dir, "files", filePath), "utf8");
    },
  };
}

/**
 * Every data shape in an interview, as zod schemas.
 *
 * Two kinds of schema live here:
 *   - "Draft" schemas describe what we ask Gemma to write. They are small on purpose,
 *     because a model fills in a short form more reliably than a long one.
 *   - The full schemas add the fields our own code is responsible for (ids, rounds, flags).
 */
import { z } from "zod";

// ---- settings ------------------------------------------------------------------------------

export const PersonaSchema = z.enum(["friendly", "tough"]);
export type Persona = z.infer<typeof PersonaSchema>;

export const RoundSchema = z.enum(["overview", "decisions", "deep-dive", "failure-scale", "wrap-up"]);
export type Round = z.infer<typeof RoundSchema>;

export const SettingsSchema = z.object({
  persona: PersonaSchema.default("tough"),
  /** Number of main questions (follow-ups come on top). */
  mainQuestions: z.number().int().min(5).max(12).default(8),
  maxFollowUps: z.number().int().min(0).max(2).default(2),
  targetRole: z.string().default("Software engineer (campus placement)"),
});
export type Settings = z.infer<typeof SettingsSchema>;

// ---- project brief -------------------------------------------------------------------------

export const HookKindSchema = z.enum(["file", "function", "decision", "risk", "ai-authored"]);

/** What Gemma writes after reading the repo. */
export const BriefDraftSchema = z.object({
  summary: z.string().min(1),
  stack: z.array(z.string()),
  components: z.array(z.object({ name: z.string(), purpose: z.string(), files: z.array(z.string()) })),
  decisions: z.array(z.string()),
  risks: z.array(z.string()),
  hooks: z.array(
    z.object({
      kind: z.enum(["file", "function", "decision", "risk"]),
      /** Short label for the thing to ask about, for example a function name or a design choice. */
      ref: z.string(),
      /** The file this hook is about, or null when it is not tied to one file. */
      file: z.string().nullable(),
      why: z.string(),
    }),
