// ---- evaluation ----------------------------------------------------------------------------

/** What Gemma writes after reading the candidate's answer. */
export const EvaluationDraftSchema = z.object({
  answerSummary: z.string(),
  score: z.number().int().min(0).max(4),
  good: z.array(z.string()),
  missing: z.array(z.string()),
