export type EvaluationDraft = z.infer<typeof EvaluationDraftSchema>;

export const EvaluationSchema = z.object({
  questionId: z.string(),
  answerSummary: z.string(),
  score: z.number().int().min(0).max(4),
  good: z.array(z.string()),
  missing: z.array(z.string()),
