  weakSpots: z.array(WeakSpotSchema),
  revisionList: z.array(z.string()),
  likelyNextQuestions: z.array(z.string()),
  deliverySummary: z.string().nullable(),
  progressVsLast: z.array(z.object({ topic: z.string(), before: z.number(), after: z.number() })),
});
export type Report = z.infer<typeof ReportSchema>;

/**
 * Every prompt Viva sends to Gemma, as plain template functions.
 * Keeping them in one file makes them easy to read, compare and quote.
 */
import type { FileContent } from "../ingest/types";
import type { Hook, InterviewState, Persona, Question, Round } from "./schemas";

// ---- personas ------------------------------------------------------------------------------

const PERSONA_INSTRUCTIONS: Record<Persona, string> = {
  friendly:
    "You are a friendly HR-round interviewer at a campus placement drive. You are warm and encouraging, " +
    "you use simple language, and you care about whether the candidate can explain their own work clearly. " +
    "You still expect real answers and you ask for an example when an answer is vague.",
  tough:
    "You are a tough tech lead interviewing a final-year student. You are direct and unsentimental. " +
    "You do not accept buzzwords: you ask why, what breaks, and what the alternative was. " +
    "You are never rude, but you do not praise an answer that has not earned it.",
};

export function interviewerInstructions(persona: Persona, targetRole: string): string {
  return [
    PERSONA_INSTRUCTIONS[persona],
    `The candidate is applying for: ${targetRole}.`,
    "You are interviewing them about ONE project that they built. Only ask about this project.",
    "Ask exactly one question at a time, in at most two sentences. Never answer the question yourself.",
    "Only mention file paths that appear in the list of real files you are given. Never invent a file, function or library.",
  ].join("\n");
}

// ---- project brief -------------------------------------------------------------------------

export const BRIEF_INSTRUCTIONS =
  "You are a senior engineer preparing to interview a student about a project they built. " +
  "You read their repository and write a short, factual brief. " +
  "You only state what the files show. You never invent files, functions or features.";

function formatFiles(contents: FileContent[]): string {
  return contents
    .map((file) => `--- ${file.path}${file.truncated ? " (truncated)" : ""} ---\n${file.content}`)
    .join("\n\n");
}

export function briefPrompt(input: { filePaths: string[]; contents: FileContent[]; correction?: string }): string {
  return [
    "ALL FILE PATHS IN THE REPO:",
    input.filePaths.join("\n"),
    "",
    "CONTENTS OF THE MOST IMPORTANT FILES:",
    formatFiles(input.contents),
    "",
    input.correction ? `THE CANDIDATE ADDED THIS CORRECTION (trust it): ${input.correction}\n` : "",
    "Write the project brief:",
    "- summary: 2 or 3 sentences on what the project does and how it is built.",
    "- stack: languages, frameworks and services actually used.",
    "- components: 3 to 6 main parts, each with its purpose and the files that implement it.",
    "- decisions: design decisions visible in the code (for example a database choice or an API design).",
    "- risks: things that could fail, be slow, or be insecure, as visible in the code.",
    "- hooks: 6 to 10 specific things worth asking about in an interview. Mix the kinds:",
    '  "file" or "function" hooks must set `file` to a path copied exactly from ALL FILE PATHS;',
    '  "decision" and "risk" hooks set `file` to the related path, or null if there is none.',
    "Every file path you write must be copied exactly from ALL FILE PATHS IN THE REPO.",
  ].join("\n");
}

// ---- questions -----------------------------------------------------------------------------

const ROUND_GOALS: Record<Round, string> = {
  overview: "Open the interview. Ask the candidate to walk you through the project: what it does, for whom, and how it is put together.",
  decisions: "Ask WHY a specific design decision was made and what alternative was considered.",
  "deep-dive": "Ask how a specific piece of the code works. Name the file. The candidate should have to explain the logic, not just describe the feature.",
  "failure-scale": "Ask what happens when something fails, or how this would behave with 100 times the users or data.",
  "wrap-up": "Close the interview. Ask what they would change or build next if they had another month, and why.",
};

/** A compact transcript so the model knows what was already asked and answered. */
function formatHistory(state: InterviewState): string {
  if (state.questions.length === 0) return "(nothing asked yet)";
  return state.questions
    .map((question) => {
      const answer = state.answers.find((a) => a.questionId === question.id);
      const answerText = !answer ? "(not answered yet)" : answer.skipped ? "(skipped)" : answer.text.slice(0, 400);
      return `Q (${question.round}): ${question.text}\nA: ${answerText}`;
    })
    .join("\n");
}

function formatBrief(state: InterviewState): string {
  const { brief } = state;
  return [
    `Project: ${state.repoLabel}`,
    `Summary: ${brief.summary}`,
    `Stack: ${brief.stack.join(", ")}`,
    `Decisions: ${brief.decisions.join(" | ")}`,
    `Risks: ${brief.risks.join(" | ")}`,
    state.userCorrection ? `Candidate's correction: ${state.userCorrection}` : "",
  ]
    .filter(Boolean)
    .join("\n");
}

export function questionPrompt(input: {
  state: InterviewState;
  round: Round;
  hook?: Hook;
  /** Content of the hook's file, when there is one. */
  file?: FileContent;
  /** A topic from a previous session to retest (Phase 2 memory). */
  retestTopic?: string;
}): string {
  const { state, round, hook, file, retestTopic } = input;
  return [
    "PROJECT BRIEF:",
    formatBrief(state),
    "",
    "REAL FILE PATHS:",
    state.filePaths.slice(0, 200).join("\n"),
    "",
    "INTERVIEW SO FAR:",
    formatHistory(state),
    "",
    `THIS QUESTION'S ROUND: ${round}. ${ROUND_GOALS[round]}`,
    hook ? `ASK ABOUT THIS: (${hook.kind}) ${hook.ref}. Why it matters: ${hook.why}` : "",
    file ? `CODE FROM ${file.path}:\n${file.content}` : "",
    retestTopic ? `The candidate struggled with "${retestTopic}" in their last session. Retest that topic now and say that you are coming back to it.` : "",
    "",
    "Write the next question. Do not repeat a question already asked.",
    "- text: the question, at most two sentences, spoken directly to the candidate.",
    "- file: the one file path the question is about, copied exactly from REAL FILE PATHS, or null.",
    "- rubric.mustMention: 2 to 4 points a correct answer has to include.",
    "- rubric.goodSignals: 1 to 3 things that would make the answer excellent (trade-offs, alternatives).",
    "- rubric.redFlags: 1 to 3 signs the candidate does not understand their own code.",
  ]
    .filter((line) => line !== "")
    .join("\n");
}

// ---- evaluation ----------------------------------------------------------------------------

export const SCORING_RUBRIC = [
  "0 = no answer, or wrong",
  "1 = vague, not specific to this project",
  "2 = correct but shallow",
  "3 = solid and specific",
  "4 = excellent, with trade-offs or alternatives",
].join("\n");

export function evaluationPrompt(input: {
  state: InterviewState;
  question: Question;
  answer: string;
  /** False when the follow-up limit for this question is already reached. */
  followUpAllowed: boolean;
}): string {
  const { state, question, answer, followUpAllowed } = input;
  return [
    "PROJECT BRIEF:",
    formatBrief(state),
    "",
    `QUESTION (${question.round}): ${question.text}`,
    `A good answer must mention: ${question.rubric.mustMention.join("; ") || "(no rubric)"}`,
    `Excellent if it shows: ${question.rubric.goodSignals.join("; ") || "(none listed)"}`,
    `Red flags: ${question.rubric.redFlags.join("; ") || "(none listed)"}`,
    "",
    `CANDIDATE'S ANSWER:\n"""${answer}"""`,
    "",
    "Evaluate the answer. Judge only what the candidate actually said.",
    `SCORE SCALE:\n${SCORING_RUBRIC}`,
    "- answerSummary: one sentence saying what the candidate claimed.",
    "- good: points they got right (may be empty).",
    "- missing: rubric points they did not cover (may be empty).",
    followUpAllowed
      ? [
          "- followUp: decide whether one follow-up question is worth asking.",
          "  Ask one when the answer was vague, contained a claim worth testing, or skipped a must-mention point.",
          "  The follow-up MUST build on something the candidate actually said:",
          "  set `quote` to a short phrase (3 to 12 words) copied word for word from their answer,",
          "  and write `question` so that it refers to that phrase.",
          "  If no follow-up is needed, set ask to false and question and quote to null.",
        ].join("\n")
      : "- followUp: set ask to false, question and quote to null (the follow-up limit is reached).",
  ].join("\n");
}

// ---- report --------------------------------------------------------------------------------

export const REPORT_INSTRUCTIONS =
  "You are an interview coach writing feedback for a student after a mock interview about their own project. " +
  "Be specific and practical. Base everything on the transcript you are given; do not invent events.";

export function reportPrompt(state: InterviewState): string {
  const transcript = state.questions
    .map((question) => {
      const evaluation = state.evaluations.find((e) => e.questionId === question.id);
      if (!evaluation) return "";
      return [
        `Q (${question.round}): ${question.text}`,
        `Answer summary: ${evaluation.skipped ? "(skipped)" : evaluation.answerSummary}`,
        `Score: ${evaluation.score}/4`,
        `Got right: ${evaluation.good.join("; ") || "-"}`,
        `Missed: ${evaluation.missing.join("; ") || "-"}`,
      ].join("\n");
    })
    .filter(Boolean)
    .join("\n\n");

  return [
    "PROJECT BRIEF:",
    formatBrief(state),
    "",
    "EVALUATED TRANSCRIPT:",
    transcript,
    "",
    "Write the coaching part of the report:",
    "- strengths: 2 to 4 things the candidate did well, each tied to a specific answer.",
    "- weakSpots: the 3 to 5 topics they most need to work on. `topic` is a short name; `evidence` is what they said or missed.",
    "- revisionList: 4 to 8 concrete things to revise before a real interview (for example 'how JWT refresh tokens are rotated').",
    "- likelyNextQuestions: exactly 5 questions a real interviewer would probably ask about this project next.",
  ].join("\n");
}

/** Project brief: Gemma reads the selected files and writes a brief; our code then checks every path in it. */
import { loadContents, selectFiles } from "../ingest/select";
import type { RepoSource, SelectedFile } from "../ingest/types";
import { generateStructured, type GenerateFn, type StructuredMeta } from "../llm/structured";
import { BRIEF_INSTRUCTIONS, briefPrompt } from "./prompts";
import { BriefDraftSchema, type BriefDraft, type ProjectBrief } from "./schemas";

/** The model sometimes writes "./src/a.ts" or "src\\a.ts" for a real "src/a.ts". Treat those as the same path. */
export function normalizePath(path: string): string {
  return path.trim().replaceAll("\\", "/").replace(/^\.\//, "").replace(/^\//, "");
}

/**
 * Checks every file path in the model's draft against the real file list.
 * Invented paths are removed and counted; the count becomes a quality metric.
 *
 * - A component keeps only its real files.
 * - A "file" or "function" hook with an invented path is dropped (it has nothing real to point at).
 * - A "decision" or "risk" hook with an invented path keeps its text but loses the path.
 */
export function validateBrief(draft: BriefDraft, filePaths: string[]): { brief: ProjectBrief; inventedPathsDropped: number } {
  const known = new Set(filePaths);
  let dropped = 0;

  const components = draft.components.map((component) => {
    const files = component.files.map(normalizePath).filter((file) => known.has(file));
    dropped += component.files.length - files.length;
    return { ...component, files };
  });

  const hooks: ProjectBrief["hooks"] = [];
  for (const hook of draft.hooks) {
    const file = hook.file ? normalizePath(hook.file) : null;
    const isReal = file !== null && known.has(file);
    if (file !== null && !isReal) dropped += 1;

    const needsFile = hook.kind === "file" || hook.kind === "function";
    if (needsFile && !isReal) continue;
    hooks.push({ id: `h${hooks.length + 1}`, kind: hook.kind, ref: hook.ref, file: isReal ? file : null, why: hook.why });
  }

  return {
    brief: { summary: draft.summary, stack: draft.stack, components, decisions: draft.decisions, risks: draft.risks, hooks },
    inventedPathsDropped: dropped,
  };
}

/** Used when the model fails twice: a plain brief built only from facts we already have. */
export function fallbackBrief(label: string, selected: SelectedFile[]): BriefDraft {
  return {
    summary: `Viva could not analyse ${label} automatically, so this brief only lists its main files.`,
    stack: [],
    components: [],
    decisions: [],
    risks: [],
    hooks: selected
      .filter((file) => file.reason === "source file" || file.reason === "entry point")
      .slice(0, 6)
      .map((file) => ({ kind: "file" as const, ref: file.path, file: file.path, why: `One of the project's main files (${file.reason}).` })),
  };
}

export type BriefResult = {
  brief: ProjectBrief;
  filesUsed: SelectedFile[];
  inventedPathsDropped: number;
  meta: StructuredMeta;
};

export async function createBrief(source: RepoSource, options: { correction?: string; generate?: GenerateFn } = {}): Promise<BriefResult> {
  const filesUsed = selectFiles(source.files);
  const contents = await loadContents(source, filesUsed);
  const filePaths = source.files.map((file) => file.path);

  const { value, meta } = await generateStructured({
    instructions: BRIEF_INSTRUCTIONS,
    // The path list is capped so a huge repo cannot blow the prompt up.
    prompt: briefPrompt({ filePaths: filePaths.slice(0, 400), contents, correction: options.correction }),
    schema: BriefDraftSchema,
    fallback: fallbackBrief(source.label, filesUsed),
    generate: options.generate,
  });

  const { brief, inventedPathsDropped } = validateBrief(value, filePaths);
  return { brief, filesUsed, inventedPathsDropped, meta };
}

/**
 * The interview state machine. Pure functions only: no model calls, no I/O.
 * Given the state, these decide what happens next. Gemma decides what to say; this code decides the flow.
 */
import type { Evaluation, Hook, InterviewState, ProjectBrief, ProvenanceEntry, Question, Round, Settings, WeakSpot } from "./schemas";
import { SettingsSchema } from "./schemas";

/**
 * Decides the round of every main question up front.
 * Always one overview question first and one wrap-up last; the middle is split between
 * decisions, deep dive (the largest share) and failure/scale.
 * Example for 8: overview, decisions x2, deep-dive x3, failure-scale, wrap-up.
 */
export function planRounds(mainQuestions: number): Round[] {
  const middle = mainQuestions - 2;
  const decisions = Math.max(1, Math.floor(middle / 3));
  const failure = Math.max(1, Math.floor(middle / 4));
  const deepDive = middle - decisions - failure;
  return [
    "overview",
    ...Array<Round>(decisions).fill("decisions"),
    ...Array<Round>(deepDive).fill("deep-dive"),
    ...Array<Round>(failure).fill("failure-scale"),
    "wrap-up",
  ];
}

export function createInterviewState(input: {
  repoId: string;
  repoLabel: string;
  filePaths: string[];
  brief: ProjectBrief;
  provenance?: ProvenanceEntry[];
  userCorrection?: string;
  previousWeakSpots?: WeakSpot[];
  settings?: Partial<Settings>;
}): InterviewState {
  const settings = SettingsSchema.parse(input.settings ?? {});
  return {
    repoId: input.repoId,
    repoLabel: input.repoLabel,
    filePaths: input.filePaths,
    brief: input.brief,
    provenance: input.provenance ?? [],
    userCorrection: input.userCorrection,
    previousWeakSpots: input.previousWeakSpots ?? [],
    settings,
    roundPlan: planRounds(settings.mainQuestions),
    questions: [],
    answers: [],
    evaluations: [],
    delivery: [],
    endedEarly: false,
  };
}

export function mainQuestionCount(state: InterviewState): number {
  return state.questions.filter((question) => !question.isFollowUp).length;
}

/** The question waiting for an answer, if any. */
export function pendingQuestion(state: InterviewState): Question | undefined {
  const last = state.questions[state.questions.length - 1];
  if (!last) return undefined;
  return state.answers.some((answer) => answer.questionId === last.id) ? undefined : last;
}

/** A follow-up belongs to the main question it grew from, even a follow-up of a follow-up. */
export function mainQuestionOf(state: InterviewState, question: Question): Question {
  let current = question;
  while (current.isFollowUp && current.parentId) {
    const parent = state.questions.find((q) => q.id === current.parentId);
    if (!parent) break;
    current = parent;
  }
  return current;
}

export function followUpCount(state: InterviewState, mainQuestionId: string): number {
  return state.questions.filter((q) => q.isFollowUp && mainQuestionOf(state, q).id === mainQuestionId).length;
}

/** May the answer to this question get a follow-up? The limit is per main question. */
export function followUpAllowed(state: InterviewState, question: Question): boolean {
  const main = mainQuestionOf(state, question);
  return followUpCount(state, main.id) < state.settings.maxFollowUps;
}

/**
 * The follow-up rule. The model proposes; this code decides:
 * no follow-up on a skipped answer, on a failed evaluation, on an excellent answer, or past the limit.
 */
export function shouldFollowUp(state: InterviewState, question: Question, evaluation: Evaluation): boolean {
  if (evaluation.skipped || !evaluation.evaluated) return false;
  if (evaluation.score >= 4) return false;
  if (!evaluation.followUp.ask) return false;
  return followUpAllowed(state, question);
}

export type NextStep = { kind: "ask-main"; round: Round; index: number } | { kind: "done" };

/** What comes next when no follow-up is being asked: the next main question, or the end. */
export function nextMainStep(state: InterviewState): NextStep {
  const asked = mainQuestionCount(state);
  if (state.endedEarly || asked >= state.roundPlan.length) return { kind: "done" };
  return { kind: "ask-main", round: state.roundPlan[asked], index: asked };
}

export function isFinished(state: InterviewState): boolean {
  return !pendingQuestion(state) && nextMainStep(state).kind === "done";
}

/** Which kinds of hook suit which round. Overview and wrap-up are asked without a hook. */
const HOOK_KINDS_BY_ROUND: Record<Round, Hook["kind"][]> = {
  overview: [],
  decisions: ["decision"],
  "deep-dive": ["ai-authored", "function", "file"],
  "failure-scale": ["risk"],
  "wrap-up": [],
};

/**
 * Picks the hook for the next main question: the first unused hook of a kind that suits the round.
 * AI-authored hooks come first in the deep dive so that at least one such question is asked.
 */
export function pickHook(state: InterviewState, round: Round): Hook | undefined {
  const used = new Set(state.questions.map((question) => question.hookId).filter(Boolean));
  for (const kind of HOOK_KINDS_BY_ROUND[round]) {
    const hook = state.brief.hooks.find((h) => h.kind === kind && !used.has(h.id));
    if (hook) return hook;
  }
  return undefined;
}

/** Ids look like "q3" for main questions and "q3.1" for their follow-ups. */
export function nextQuestionId(state: InterviewState, parent?: Question): string {
  if (!parent) return `q${mainQuestionCount(state) + 1}`;
  const main = mainQuestionOf(state, parent);
  return `${main.id}.${followUpCount(state, main.id) + 1}`;
}

export function progress(state: InterviewState): { asked: number; total: number; round: Round | null } {
  const asked = mainQuestionCount(state);
  const last = state.questions[state.questions.length - 1];
  return { asked, total: state.roundPlan.length, round: last ? mainQuestionOf(state, last).round : null };
}

/**
 * One interview turn: evaluate the last answer, then decide and produce what comes next.
 *
 * The model writes questions and evaluations; the state machine in state.ts decides the flow.
 * In Phase 2 a Mastra agent with tools takes over the question writing; the flow stays the same.
 */
import { PER_FILE_CAP_CHARS } from "../ingest/select";
import type { FileContent } from "../ingest/types";
import { generateStructured, type GenerateFn, type StructuredMeta } from "../llm/structured";
import { normalizePath } from "./brief";
import { evaluationPrompt, interviewerInstructions, questionPrompt } from "./prompts";
import {
  EvaluationDraftSchema,
  QuestionDraftSchema,
  type Evaluation,
  type InterviewState,
  type Question,
  type QuestionDraft,
  type Round,
} from "./schemas";
import { followUpAllowed, isFinished, nextMainStep, nextQuestionId, pendingQuestion, pickHook, shouldFollowUp } from "./state";

/** What a turn needs from the outside world. Tests pass fakes for both. */
export type TurnDeps = {
  /** Reads a file from the candidate's repo. Only ever called with a validated path. */
  readFile: (path: string) => Promise<string>;
  generate?: GenerateFn;
};

/** Per-turn quality facts. These become Sentry span attributes in Phase 7 and eval metrics now. */
export type TurnQuality = {
  /** The model named a file that does not exist; it was removed before the user saw it. */
  inventedPathDropped: boolean;
  /** A deep-dive question that names a real file. null when the question is not a deep dive. */
  questionNamesRealFile: boolean | null;
  /** A follow-up whose quoted phrase really appears in the candidate's answer. null when there is no follow-up. */
  followUpReferencesAnswer: boolean | null;
  jsonRepairUsed: boolean;
  fallbackUsed: boolean;
};

/** Safe questions for when the model fails twice. One per round, generic but always valid. */
const FALLBACK_QUESTIONS: Record<Round, string> = {
  overview: "Walk me through your project: what does it do, and how is it put together?",
  decisions: "Pick one technical decision you made in this project. Why did you choose it, and what was the alternative?",
  "deep-dive": "Pick the most complex part of your code and explain how it works, step by step.",
  "failure-scale": "What is the first thing that would break if this project had 100 times more users, and how would you fix it?",
  "wrap-up": "If you had one more month on this project, what would you change or build next, and why?",
};

function fallbackQuestion(round: Round): QuestionDraft {
  return { text: FALLBACK_QUESTIONS[round], file: null, rubric: { mustMention: [], goodSignals: [], redFlags: [] } };
}

/** Lower-case and collapse whitespace so a quote still matches if spacing or case differs. */
function normalizeText(text: string): string {
  return text.toLowerCase().replace(/\s+/g, " ").trim();
}

/** The cheap grounding check: is the phrase the model says it is following up on really in the answer? */
export function quoteAppearsInAnswer(quote: string | null, answer: string): boolean {
  if (!quote) return false;
  const cleaned = normalizeText(quote).replace(/^["'“”]+|["'“”.]+$/g, "");
  return cleaned.length >= 8 && normalizeText(answer).includes(cleaned);
}

async function readForPrompt(deps: TurnDeps, path: string): Promise<FileContent | undefined> {
  try {
    const text = await deps.readFile(path);
    return { path, content: text.slice(0, PER_FILE_CAP_CHARS), truncated: text.length > PER_FILE_CAP_CHARS };
  } catch {
    return undefined;
  }
}

/** Writes the next main question for the given round. */
export async function askMainQuestion(
  state: InterviewState,
  round: Round,
  deps: TurnDeps,
): Promise<{ question: Question; meta: StructuredMeta; quality: TurnQuality }> {
  const hook = pickHook(state, round);
  const file = hook?.file ? await readForPrompt(deps, hook.file) : undefined;
  // The first question of a session retests a weak spot from last time, when there is one (Phase 2 memory).
  const retestTopic = state.questions.length === 0 ? state.previousWeakSpots[0]?.topic : undefined;

  const { value: draft, meta } = await generateStructured({
    instructions: interviewerInstructions(state.settings.persona, state.settings.targetRole),
    prompt: questionPrompt({ state, round, hook, file, retestTopic }),
    schema: QuestionDraftSchema,
    fallback: fallbackQuestion(round),
    generate: deps.generate,
  });

  // Validate the path the model named before it can reach the user.
  const named = draft.file ? normalizePath(draft.file) : null;
  const namedIsReal = named !== null && state.filePaths.includes(named);

  const question: Question = {
    id: nextQuestionId(state),
    round,
    persona: state.settings.persona,
    text: draft.text,
    hookId: hook?.id,
    filesRead: [...new Set([file?.path, namedIsReal ? named : undefined].filter((p): p is string => Boolean(p)))],
    rubric: draft.rubric,
    isFollowUp: false,
    aboutAiCode: hook?.kind === "ai-authored",
  };

  return {
    question,
    meta,
    quality: {
      inventedPathDropped: named !== null && !namedIsReal,
      questionNamesRealFile: round === "deep-dive" ? namedIsReal : null,
      followUpReferencesAnswer: null,
      jsonRepairUsed: meta.repaired,
      fallbackUsed: meta.usedFallback,
    },
  };
}

/** Phrases that count as "I don't know". They are scored 0 without a model call. */
const DONT_KNOW = /^(i\s*(do\s*not|don'?t)\s*know|no\s*idea|not\s*sure|idk|skip|pass)[\s.!]*$/i;

export function isSkip(answer: string): boolean {
  return answer.trim() === "" || DONT_KNOW.test(answer.trim());
}

/** Scores the answer and, if a follow-up is warranted, returns it as the next question. */
export async function evaluateAnswer(
  state: InterviewState,
  question: Question,
  answer: string,
  deps: TurnDeps,
): Promise<{ evaluation: Evaluation; followUp?: Question; meta?: StructuredMeta; quality: TurnQuality }> {
  const quality: TurnQuality = {
    inventedPathDropped: false,
    questionNamesRealFile: null,
    followUpReferencesAnswer: null,
    jsonRepairUsed: false,
    fallbackUsed: false,
  };

  // A skip is scored by code, not by the model: 0 points, and the rubric goes on the revision list.
  if (isSkip(answer)) {
    return {
      evaluation: {
        questionId: question.id,
        answerSummary: "Skipped or did not know.",
        score: 0,
        good: [],
        missing: question.rubric.mustMention,
        followUp: { ask: false, reason: "Skipped answers get no follow-up." },
        evaluated: true,
        skipped: true,
      },
      quality,
    };
  }

  const allowed = followUpAllowed(state, question);
  const { value: draft, meta } = await generateStructured({
    instructions: interviewerInstructions(state.settings.persona, state.settings.targetRole),
    prompt: evaluationPrompt({ state, question, answer, followUpAllowed: allowed }),
    schema: EvaluationDraftSchema,
    // A placeholder that is marked as not evaluated, so it never counts towards the score.
    fallback: {
      answerSummary: "Viva could not evaluate this answer automatically.",
      score: 0,
      good: [],
      missing: [],
      followUp: { ask: false, question: null, quote: null, reason: "Evaluation failed." },
    },
    generate: deps.generate,
  });
  quality.jsonRepairUsed = meta.repaired;
  quality.fallbackUsed = meta.usedFallback;

  const evaluation: Evaluation = {
    questionId: question.id,
    answerSummary: draft.answerSummary,
    score: draft.score,
    good: draft.good,
    missing: draft.missing,
    followUp: { ask: draft.followUp.ask && Boolean(draft.followUp.question), reason: draft.followUp.reason },
    evaluated: !meta.usedFallback,
    skipped: false,
  };

  if (!shouldFollowUp(state, question, evaluation) || !draft.followUp.question) {
    evaluation.followUp.ask = false;
    return { evaluation, meta, quality };
  }

  quality.followUpReferencesAnswer = quoteAppearsInAnswer(draft.followUp.quote, answer);
  const followUp: Question = {
    id: nextQuestionId(state, question),
    round: question.round,
    persona: state.settings.persona,
    text: draft.followUp.question,
    hookId: question.hookId,
    filesRead: [],
    // A follow-up is judged against its parent's rubric: it digs into the same topic.
    rubric: question.rubric,
    isFollowUp: true,
    parentId: question.id,
    aboutAiCode: question.aboutAiCode,
  };
  return { evaluation, followUp, meta, quality };
}

export type TurnResult = {
  state: InterviewState;
  evaluation?: Evaluation;
  nextQuestion?: Question;
  done: boolean;
  /** Short lines describing what happened, for the "reading src/auth.ts..." status text. */
  toolActivity: string[];
  quality: TurnQuality[];
  metas: StructuredMeta[];
};

/**
 * The whole turn, as /api/turn will call it.
 * - With no pending question (start of the interview): asks the first question.
 * - With a pending question: records and evaluates `answer`, then asks a follow-up or the next
 *   main question, or finishes.
 * The input state is not modified; a new state is returned.
 */
export async function runTurn(input: InterviewState, answer: string | undefined, deps: TurnDeps): Promise<TurnResult> {
  const state: InterviewState = structuredClone(input);
  const result: TurnResult = { state, done: false, toolActivity: [], quality: [], metas: [] };

  const pending = pendingQuestion(state);
  let followUp: Question | undefined;

  if (pending) {
    const text = answer ?? "";
    const evaluated = await evaluateAnswer(state, pending, text, deps);
    state.answers.push({ questionId: pending.id, text, skipped: evaluated.evaluation.skipped });
    state.evaluations.push(evaluated.evaluation);
    result.evaluation = evaluated.evaluation;
    result.quality.push(evaluated.quality);
    if (evaluated.meta) result.metas.push(evaluated.meta);
    followUp = evaluated.followUp;
  }

  if (followUp && !state.endedEarly) {
    state.questions.push(followUp);
    result.nextQuestion = followUp;
    return result;
  }

  const step = nextMainStep(state);
  if (step.kind === "done") {
    result.done = isFinished(state);
    return result;
  }

  const asked = await askMainQuestion(state, step.round, deps);
  state.questions.push(asked.question);
  result.nextQuestion = asked.question;
  result.quality.push(asked.quality);
  result.metas.push(asked.meta);
  result.toolActivity.push(...asked.question.filesRead.map((path) => `read ${path}`));
  return result;
}

/** "End early": no more questions; the report covers what was answered. */
export function endEarly(input: InterviewState): InterviewState {
  const state = structuredClone(input);
  const pending = pendingQuestion(state);
  // An unanswered question is removed rather than counted as a skip: the candidate never got to it.
  if (pending) state.questions = state.questions.filter((question) => question.id !== pending.id);
  state.endedEarly = true;
  return state;
}

/**
 * The final report. All numbers (scores, averages, readiness) are computed here in code.
 * Gemma only writes the coaching text: strengths, weak spots, revision list, likely next questions.
 */
import { generateStructured, type GenerateFn, type StructuredMeta } from "../llm/structured";
import { REPORT_INSTRUCTIONS, reportPrompt } from "./prompts";
import { ReportDraftSchema, type InterviewState, type Report, type ReportDraft, type Round } from "./schemas";
import { mainQuestionOf } from "./state";

/** Average of the evaluated answers, rounded to one decimal. 0 when nothing was evaluated. */
export function averageScore(scores: number[]): number {
  if (scores.length === 0) return 0;
  return Math.round((scores.reduce((sum, score) => sum + score, 0) / scores.length) * 10) / 10;
}

/** Maps the 0 to 4 average onto a plain-language readiness label. */
export function readinessLabel(average: number, answered: number): string {
  if (answered === 0) return "Not enough answers to judge";
  if (average < 1.5) return "Not ready yet";
  if (average < 2.5) return "Getting there";
  if (average < 3.25) return "Nearly ready";
  return "Interview ready";
}

export function computeStats(state: InterviewState): {
  overall: number;
  readiness: string;
  byRound: Partial<Record<Round, number>>;
  perQuestion: Report["perQuestion"];
} {
  const perQuestion: Report["perQuestion"] = [];
  for (const question of state.questions) {
    const evaluation = state.evaluations.find((e) => e.questionId === question.id);
    if (!evaluation) continue;
    perQuestion.push({
      questionId: question.id,
      round: question.round,
      question: question.text,
      answerSummary: evaluation.answerSummary,
      score: evaluation.score,
      good: evaluation.good,
      missing: evaluation.missing,
      isFollowUp: question.isFollowUp,
      aboutAiCode: question.aboutAiCode,
      skipped: evaluation.skipped,
    });
  }

  // Placeholder evaluations (model failed) are left out of every average.
  const counted = state.evaluations.filter((evaluation) => evaluation.evaluated);
  const overall = averageScore(counted.map((evaluation) => evaluation.score));

  const byRound: Partial<Record<Round, number>> = {};
  for (const round of new Set(state.roundPlan)) {
    const scores = counted
      .filter((evaluation) => {
        const question = state.questions.find((q) => q.id === evaluation.questionId);
        return question !== undefined && mainQuestionOf(state, question).round === round;
      })
      .map((evaluation) => evaluation.score);
    if (scores.length > 0) byRound[round] = averageScore(scores);
  }

  return { overall, readiness: readinessLabel(overall, counted.length), byRound, perQuestion };
}

/** Used when the model fails twice: coaching text assembled from the evaluations themselves. */
export function fallbackReportDraft(state: InterviewState): ReportDraft {
  const weakest = state.evaluations
    .filter((evaluation) => evaluation.evaluated && evaluation.score <= 2)
    .sort((a, b) => a.score - b.score)
    .slice(0, 5);
  const questionText = (id: string) => state.questions.find((q) => q.id === id)?.text ?? id;
  return {
    strengths: state.evaluations.flatMap((evaluation) => evaluation.good).slice(0, 4),
    weakSpots: weakest.map((evaluation) => ({
      topic: questionText(evaluation.questionId).slice(0, 80),
      evidence: evaluation.missing.join("; ") || evaluation.answerSummary,
    })),
    revisionList: [...new Set(state.evaluations.flatMap((evaluation) => evaluation.missing))].slice(0, 8),
    likelyNextQuestions: [],
  };
}

export async function buildReport(
  state: InterviewState,
  options: { generate?: GenerateFn; today?: string } = {},
): Promise<{ report: Report; meta: StructuredMeta }> {
  const stats = computeStats(state);
  const { value: draft, meta } = await generateStructured({
    instructions: REPORT_INSTRUCTIONS,
    prompt: reportPrompt(state),
    schema: ReportDraftSchema,
    fallback: fallbackReportDraft(state),
    generate: options.generate,
  });

  const sessionDate = options.today ?? new Date().toISOString().slice(0, 10);
  const report: Report = {
    overall: stats.overall,
    readiness: stats.readiness,
    perQuestion: stats.perQuestion,
    strengths: draft.strengths,
    // The model names the weak topics; the score attached to each is the session average, a number we computed.
    weakSpots: draft.weakSpots.slice(0, 5).map((spot) => ({ ...spot, lastScore: stats.overall, sessionDate })),
    revisionList: draft.revisionList,
    likelyNextQuestions: draft.likelyNextQuestions.slice(0, 5),
    deliverySummary: null, // Phase 6
    progressVsLast: [], // Phase 2
  };
  return { report, meta };
}

function bullets(items: string[]): string {
  return items.length > 0 ? items.map((item) => `- ${item}`).join("\n") : "- (none)";
}

export function reportToMarkdown(report: Report, repoLabel: string): string {
  const questions = report.perQuestion
    .map((q) =>
      [
        `### ${q.questionId}${q.isFollowUp ? " (follow-up)" : ""} · ${q.round}${q.aboutAiCode ? " · AI-written code" : ""} · ${q.skipped ? "skipped" : `${q.score}/4`}`,
        `**Q:** ${q.question}`,
        `**Your answer:** ${q.answerSummary}`,
        q.good.length > 0 ? `**Good:** ${q.good.join("; ")}` : "",
        q.missing.length > 0 ? `**Missing:** ${q.missing.join("; ")}` : "",
      ]
        .filter(Boolean)
        .join("\n\n"),
    )
    .join("\n\n");

  return [
    `# Viva report: ${repoLabel}`,
    `**Overall:** ${report.overall}/4 · **Readiness:** ${report.readiness}`,
    `## Strengths\n${bullets(report.strengths)}`,
    `## Weak spots\n${bullets(report.weakSpots.map((spot) => `**${spot.topic}:** ${spot.evidence}`))}`,
    `## Revise before the real interview\n${bullets(report.revisionList)}`,
    `## Likely next questions\n${bullets(report.likelyNextQuestions)}`,
    report.deliverySummary ? `## How you said it\n${report.deliverySummary}` : "",
    `## Question by question\n\n${questions}`,
  ]
    .filter(Boolean)
    .join("\n\n");
}

import { describe, expect, it } from "vitest";
import { z } from "zod";
import { generateStructured, type GenerateFn } from "./structured";

const Schema = z.object({ score: z.number().int().min(0).max(4) });
const base = { instructions: "test", prompt: "score this", schema: Schema, fallback: { score: 0 } };

/** A fake model that returns the given replies in order; an Error in the list is thrown. */
function fakeModel(replies: unknown[]): { generate: GenerateFn; prompts: string[] } {
  const prompts: string[] = [];
  let call = 0;
  return {
    prompts,
    generate: async ({ prompt }) => {
      prompts.push(prompt);
      const reply = replies[call++];
      if (reply instanceof Error) throw reply;
      return { object: reply };
    },
  };
}

describe("generateStructured", () => {
  it("returns a valid first reply without repair", async () => {
    const model = fakeModel([{ score: 3 }]);
    const { value, meta } = await generateStructured({ ...base, generate: model.generate });
    expect(value).toEqual({ score: 3 });
    expect(meta.repaired).toBe(false);
    expect(meta.usedFallback).toBe(false);
    expect(model.prompts).toHaveLength(1);
  });

  it("retries once and tells the model what was wrong", async () => {
    const model = fakeModel([{ score: 9 }, { score: 2 }]);
    const { value, meta } = await generateStructured({ ...base, generate: model.generate });
    expect(value).toEqual({ score: 2 });
    expect(meta.repaired).toBe(true);
    expect(meta.usedFallback).toBe(false);
    expect(model.prompts[1]).toContain("previous reply could not be used");
  });

  it("recovers when the first call throws (timeout, network error)", async () => {
    const model = fakeModel([new Error("timed out"), { score: 1 }]);
    const { value, meta } = await generateStructured({ ...base, generate: model.generate });
    expect(value).toEqual({ score: 1 });
    expect(meta.repaired).toBe(true);
  });

  it("returns the fallback after two bad replies and never throws", async () => {
    const model = fakeModel(["not json", new Error("boom")]);
    const { value, meta } = await generateStructured({ ...base, generate: model.generate });
    expect(value).toEqual({ score: 0 });
    expect(meta.usedFallback).toBe(true);
    expect(meta.error).toContain("boom");
    expect(model.prompts).toHaveLength(2);
  });
});

import { describe, expect, it } from "vitest";
