import { describe, expect, it } from "vitest";
import type { GenerateFn } from "../llm/structured";
import { normalizePath, validateBrief } from "./brief";
import { averageScore, buildReport, computeStats, readinessLabel, reportToMarkdown } from "./report";
import type { BriefDraft, EvaluationDraft, InterviewState, ProjectBrief, QuestionDraft } from "./schemas";
import { createInterviewState, followUpCount, isFinished, mainQuestionCount, nextMainStep, pendingQuestion, pickHook, planRounds } from "./state";
import { endEarly, isSkip, quoteAppearsInAnswer, runTurn } from "./turn";

const FILES = ["README.md", "src/auth.ts", "src/db.ts"];

const BRIEF: ProjectBrief = {
  summary: "A demo API.",
  stack: ["TypeScript"],
  components: [],
  decisions: ["JWT auth"],
  risks: ["No rate limiting"],
  hooks: [
    { id: "h1", kind: "decision", ref: "JWT instead of sessions", file: null, why: "core choice" },
    { id: "h2", kind: "file", ref: "auth flow", file: "src/auth.ts", why: "central" },
    { id: "h3", kind: "risk", ref: "no rate limiting", file: null, why: "abuse" },
  ],
};

function newState(settings = {}): InterviewState {
  return createInterviewState({ repoId: "test:repo", repoLabel: "repo", filePaths: FILES, brief: BRIEF, settings });
}

const rubric = { mustMention: ["point A"], goodSignals: [], redFlags: [] };

/**
 * A fake model. It tells question prompts from evaluation prompts by their text and
 * answers with whatever the test configured.
 */
function fakeModel(options: { question?: Partial<QuestionDraft>; evaluation?: Partial<EvaluationDraft> } = {}): GenerateFn {
  return async ({ prompt }) => {
    if (prompt.includes("CANDIDATE'S ANSWER")) {
      const evaluation: EvaluationDraft = {
        answerSummary: "They explained it.",
        score: 3,
        good: ["clear"],
        missing: [],
        followUp: { ask: false, question: null, quote: null, reason: "complete" },
        ...options.evaluation,
      };
      return { object: evaluation };
    }
    if (prompt.includes("EVALUATED TRANSCRIPT")) {
      return { object: { strengths: ["s"], weakSpots: [{ topic: "t", evidence: "e" }], revisionList: ["r"], likelyNextQuestions: ["1", "2", "3", "4", "5", "6"] } };
    }
    const question: QuestionDraft = { text: "How does it work?", file: null, rubric, ...options.question };
    return { object: question };
  };
}

const deps = (generate: GenerateFn) => ({ generate, readFile: async (path: string) => `// contents of ${path}` });

describe("planRounds", () => {
  it("gives the right number of rounds, starting with overview and ending with wrap-up", () => {
    for (let n = 5; n <= 12; n++) {
      const plan = planRounds(n);
      expect(plan).toHaveLength(n);
      expect(plan[0]).toBe("overview");
      expect(plan[n - 1]).toBe("wrap-up");
      for (const round of ["decisions", "deep-dive", "failure-scale"]) expect(plan).toContain(round);
    }
  });

  it("matches the documented split for 8 questions", () => {
    expect(planRounds(8)).toEqual(["overview", "decisions", "decisions", "deep-dive", "deep-dive", "deep-dive", "failure-scale", "wrap-up"]);
  });
});

describe("validateBrief", () => {
  const draft: BriefDraft = {
    summary: "s",
    stack: [],
    components: [{ name: "auth", purpose: "p", files: ["src/auth.ts", "src/invented.ts"] }],
    decisions: [],
    risks: [],
    hooks: [
      { kind: "file", ref: "real", file: "./src/auth.ts", why: "w" },
      { kind: "function", ref: "made up", file: "src/ghost.ts", why: "w" },
      { kind: "decision", ref: "choice", file: "src/nope.ts", why: "w" },
      { kind: "risk", ref: "risk", file: null, why: "w" },
    ],
  };

  it("drops invented paths and counts them", () => {
    const { brief, inventedPathsDropped } = validateBrief(draft, FILES);
    expect(inventedPathsDropped).toBe(3);
    expect(brief.components[0].files).toEqual(["src/auth.ts"]);
    // The invented "function" hook is gone; the "decision" hook stays without its path.
    expect(brief.hooks.map((hook) => hook.ref)).toEqual(["real", "choice", "risk"]);
    expect(brief.hooks.find((hook) => hook.ref === "choice")?.file).toBeNull();
    expect(brief.hooks.map((hook) => hook.id)).toEqual(["h1", "h2", "h3"]);
  });

  it("treats ./ and backslash spellings as the same real path", () => {
    expect(normalizePath("./src\\auth.ts")).toBe("src/auth.ts");
    expect(validateBrief(draft, FILES).brief.hooks[0].file).toBe("src/auth.ts");
  });
});

describe("state machine", () => {
  it("picks hooks that suit the round and never reuses one", () => {
    const state = newState();
    expect(pickHook(state, "overview")).toBeUndefined();
    expect(pickHook(state, "decisions")?.id).toBe("h1");
    expect(pickHook(state, "deep-dive")?.id).toBe("h2");
    expect(pickHook(state, "failure-scale")?.id).toBe("h3");
  });

  it("runs a full interview: one question per turn, then done", async () => {
    let state = newState({ mainQuestions: 5 });
    const generate = fakeModel();

    let turn = await runTurn(state, undefined, deps(generate));
    expect(turn.nextQuestion?.id).toBe("q1");
    expect(turn.nextQuestion?.round).toBe("overview");
    state = turn.state;

    for (let i = 0; i < 5; i++) {
      expect(pendingQuestion(state)).toBeDefined();
      turn = await runTurn(state, "A specific and complete answer about the code.", deps(generate));
      state = turn.state;
    }

    expect(turn.done).toBe(true);
    expect(isFinished(state)).toBe(true);
    expect(mainQuestionCount(state)).toBe(5);
    expect(state.evaluations).toHaveLength(5);
    expect(nextMainStep(state)).toEqual({ kind: "done" });
  });

  it("does not modify the state it was given", async () => {
    const state = newState();
    const turn = await runTurn(state, undefined, deps(fakeModel()));
    expect(state.questions).toHaveLength(0);
    expect(turn.state.questions).toHaveLength(1);
  });

  it("asks at most maxFollowUps follow-ups per main question", async () => {
    const generate = fakeModel({
      evaluation: { score: 1, followUp: { ask: true, question: "You said it just works. How?", quote: "it just works", reason: "vague" } },
    });
    let state = (await runTurn(newState({ mainQuestions: 5, maxFollowUps: 2 }), undefined, deps(generate))).state;

    const ids: string[] = [];
    for (let i = 0; i < 4; i++) {
      const turn = await runTurn(state, "Honestly it just works for me.", deps(generate));
      state = turn.state;
      ids.push(turn.nextQuestion?.id ?? "none");
    }
    // q1 -> two follow-ups -> q2 -> first follow-up of q2
    expect(ids).toEqual(["q1.1", "q1.2", "q2", "q2.1"]);
    expect(followUpCount(state, "q1")).toBe(2);
    expect(state.questions.find((q) => q.id === "q1.2")?.parentId).toBe("q1.1");
  });

  it("scores a skip as 0 without calling the model and asks no follow-up", async () => {
    const generate = fakeModel();
    const state = (await runTurn(newState(), undefined, deps(generate))).state;

    let evaluationCalls = 0;
    const counting: GenerateFn = async (args) => {
      if (args.prompt.includes("CANDIDATE'S ANSWER")) evaluationCalls += 1;
      return generate(args);
    };
    const turn = await runTurn(state, "I don't know", deps(counting));

    expect(evaluationCalls).toBe(0);
    expect(turn.evaluation).toMatchObject({ score: 0, skipped: true, missing: ["point A"] });
    expect(turn.nextQuestion?.isFollowUp).toBe(false);
  });

  it("removes a file path the model invented and reports it", async () => {
    // Force the deep-dive round by answering the first two questions.
    const generate = fakeModel({ question: { file: "src/does-not-exist.ts" } });
    let state = newState({ mainQuestions: 5 });
    let turn = await runTurn(state, undefined, deps(generate));
    for (let i = 0; i < 2; i++) turn = await runTurn(turn.state, "A full answer with details.", deps(generate));
    state = turn.state;

    const deepDive = turn.nextQuestion!;
    expect(deepDive.round).toBe("deep-dive");
    expect(deepDive.filesRead).toEqual(["src/auth.ts"]); // the hook's real file, not the invented one
    expect(turn.quality.at(-1)).toMatchObject({ inventedPathDropped: true, questionNamesRealFile: false });
  });

  it("ending early drops the unanswered question and finishes", async () => {
    const state = (await runTurn(newState(), undefined, deps(fakeModel()))).state;
    const ended = endEarly(state);
    expect(ended.questions).toHaveLength(0);
    expect(isFinished(ended)).toBe(true);
  });
});

describe("answer checks", () => {
  it("recognises skips and I-don't-know answers", () => {
    for (const answer of ["", "  ", "skip", "I don't know", "i dont know.", "No idea", "pass"]) expect(isSkip(answer), answer).toBe(true);
    expect(isSkip("I don't know the exact number, but it uses a hash map")).toBe(false);
  });

  it("checks that a follow-up quotes the real answer", () => {
    const answer = "I used   JWT because it is Stateless and easy.";
    expect(quoteAppearsInAnswer("because it is stateless", answer)).toBe(true);
    expect(quoteAppearsInAnswer('"jwt because it is stateless."', answer)).toBe(true);
    expect(quoteAppearsInAnswer("because sessions are slow", answer)).toBe(false);
    expect(quoteAppearsInAnswer("jwt", answer)).toBe(false); // too short to prove anything
    expect(quoteAppearsInAnswer(null, answer)).toBe(false);
  });
});

describe("report", () => {
  it("averages and labels readiness", () => {
    expect(averageScore([4, 3, 2])).toBe(3);
    expect(averageScore([])).toBe(0);
    expect(readinessLabel(0, 0)).toBe("Not enough answers to judge");
    expect(readinessLabel(1.2, 5)).toBe("Not ready yet");
    expect(readinessLabel(2, 5)).toBe("Getting there");
    expect(readinessLabel(3, 5)).toBe("Nearly ready");
    expect(readinessLabel(3.5, 5)).toBe("Interview ready");
  });

  it("leaves failed evaluations out of the average", async () => {
    const state = (await runTurn(newState(), undefined, deps(fakeModel()))).state;
    state.answers.push({ questionId: "q1", text: "x", skipped: false });
    state.evaluations.push({ questionId: "q1", answerSummary: "", score: 0, good: [], missing: [], followUp: { ask: false, reason: "" }, evaluated: false, skipped: false });
    expect(computeStats(state).readiness).toBe("Not enough answers to judge");
  });

  it("builds a report with computed scores and at most 5 next questions, and exports Markdown", async () => {
    const generate = fakeModel();
    let turn = await runTurn(newState({ mainQuestions: 5 }), undefined, deps(generate));
    for (let i = 0; i < 5; i++) turn = await runTurn(turn.state, "A specific answer.", deps(generate));

    const { report } = await buildReport(turn.state, { generate, today: "2026-10-04" });
    expect(report.overall).toBe(3);
    expect(report.readiness).toBe("Nearly ready");
    expect(report.perQuestion).toHaveLength(5);
    expect(report.likelyNextQuestions).toHaveLength(5);
    expect(report.weakSpots[0]).toEqual({ topic: "t", evidence: "e", lastScore: 3, sessionDate: "2026-10-04" });

    const markdown = reportToMarkdown(report, "repo");
    expect(markdown).toContain("# Viva report: repo");
    expect(markdown).toContain("**Overall:** 3/4");
    expect(markdown).toContain("### q1 · overview · 3/4");
  });
});

/** Shared by the CLI scripts: turn a command-line target into a repo Viva can read. */
import { FIXTURE_NAMES, loadFixture, type FixtureName } from "../src/lib/ingest/fixture";
import { loadGitHubRepo, parseGitHubUrl } from "../src/lib/ingest/github";
import { loadLocalRepo } from "../src/lib/ingest/local";
import type { RepoSource } from "../src/lib/ingest/types";

/** A fixture name, a GitHub URL (or owner/repo), or a local folder path (needs LOCAL_MODE=true). */
export async function loadSource(target: string): Promise<RepoSource> {
  if ((FIXTURE_NAMES as readonly string[]).includes(target)) return loadFixture(target as FixtureName);
  if (target.startsWith("http") || (parseGitHubUrl(target) && !target.startsWith("."))) return loadGitHubRepo(target);
  return loadLocalRepo(target);
}

/**
 * Terminal interview: the whole Viva loop without a UI.
 *
 *   pnpm interview portfolio-new                      (a fixture)
 *   pnpm interview https://github.com/owner/repo tough 6
 *   pnpm interview ./my-project friendly              (needs LOCAL_MODE=true)
 *
 * Type your answer and press Enter. "skip" skips a question, "end" finishes early.
 */
import { writeFileSync } from "node:fs";
import { createInterface } from "node:readline/promises";
import { createBrief } from "../src/lib/interview/brief";
import { buildReport, reportToMarkdown } from "../src/lib/interview/report";
import { PersonaSchema } from "../src/lib/interview/schemas";
import { createInterviewState, progress } from "../src/lib/interview/state";
import { endEarly, runTurn } from "../src/lib/interview/turn";
import { loadSource } from "./load-source";

async function main() {
  const [target, personaArg, countArg] = process.argv.slice(2);
  if (!target) {
    console.log("Usage: pnpm interview <fixture | github url | folder> [friendly|tough] [5-12]");
    process.exit(1);
  }
  const persona = PersonaSchema.catch("tough").parse(personaArg);
  const mainQuestions = Number(countArg ?? 6);

  console.log(`Reading ${target} ...`);
  const source = await loadSource(target);
  const { brief, filesUsed, inventedPathsDropped, meta } = await createBrief(source);
  console.log(`\nRead ${filesUsed.length} of ${source.files.length} files in ${meta.ms} ms${meta.usedFallback ? " (model failed, fallback brief)" : ""}.`);
  console.log(`Invented paths dropped: ${inventedPathsDropped}`);
  console.log(`\n${brief.summary}\nStack: ${brief.stack.join(", ")}`);
  console.log(`Hooks:\n${brief.hooks.map((hook) => `  - (${hook.kind}) ${hook.ref}${hook.file ? ` [${hook.file}]` : ""}`).join("\n")}`);

  const io = createInterface({ input: process.stdin, output: process.stdout });
  const correction = (await io.question("\nAnything to correct about this brief? (Enter to skip) ")).trim();

  let state = createInterviewState({
    repoId: source.id,
    repoLabel: source.label,
    filePaths: source.files.map((file) => file.path),
    brief,
    userCorrection: correction || undefined,
    settings: { persona, mainQuestions },
  });
  const deps = { readFile: source.readFile };

  let turn = await runTurn(state, undefined, deps);
  while (turn.nextQuestion) {
    state = turn.state;
    const { asked, total } = progress(state);
    const question = turn.nextQuestion;
    for (const activity of turn.toolActivity) console.log(`  (${activity})`);
    console.log(`\n[${question.round} · ${asked}/${total}${question.isFollowUp ? " · follow-up" : ""}] ${question.text}`);

    const answer = await io.question("> ");
    if (answer.trim().toLowerCase() === "end") {
      state = endEarly(state);
      break;
    }
    turn = await runTurn(state, answer, deps);
    state = turn.state;
    if (turn.evaluation) console.log(`  score ${turn.evaluation.score}/4${turn.evaluation.skipped ? " (skipped)" : ""}`);
  }
  io.close();

  console.log("\nWriting the report ...");
  const { report } = await buildReport(state);
  const markdown = reportToMarkdown(report, source.label);
  writeFileSync("viva-report.md", markdown);
  console.log(`\n${markdown}\n\nSaved to viva-report.md`);
}

main();

/** Shared by the CLI scripts: turn a command-line target into a repo Viva can read. */
import { existsSync } from "node:fs";
import { FIXTURE_NAMES, loadFixture, type FixtureName } from "../src/lib/ingest/fixture";
import { loadGitHubRepo } from "../src/lib/ingest/github";
import { loadLocalRepo } from "../src/lib/ingest/local";
import type { RepoSource } from "../src/lib/ingest/types";

/** A fixture name, a folder that exists on disk (needs LOCAL_MODE=true), or else a GitHub URL / owner/repo. */
export async function loadSource(target: string): Promise<RepoSource> {
  if ((FIXTURE_NAMES as readonly string[]).includes(target)) return loadFixture(target as FixtureName);
  if (!target.startsWith("http") && existsSync(target)) return loadLocalRepo(target);
  return loadGitHubRepo(target);
}

/**
 * Agent evals: run scripted interviews against the fixture repos and print quality metrics.
 *
 *   pnpm eval                      (both fixtures, all three candidates)
 *   pnpm eval portfolio-new        (one fixture)
 *
 * Three scripted candidates answer every question:
 *   - good:  a simulated student (Gemma, shown the relevant file) who answers specifically
 *   - vague: canned answers with no substance
 *   - wrong: canned answers that are confidently incorrect
 *
 * What is measured:
 *   - validity:      model calls that produced schema-valid output (after at most one repair)
 *   - repair rate:   calls that needed the second attempt
 *   - real-file:     deep-dive questions that name a real file
 *   - invented:      file paths the model made up (all removed before a user would see them)
 *   - grounding:     follow-ups whose quoted phrase really appears in the answer (automatic check)
 *   - scores:        average score per candidate; good should clearly beat vague and wrong
 *   - latency:       median time of a question call and of an evaluation call
 *
 * Results are saved to fixtures/evals/ and briefs to fixtures/briefs/.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { z } from "zod";
import { FIXTURE_NAMES, loadFixture, type FixtureName } from "../src/lib/ingest/fixture";
import type { RepoSource } from "../src/lib/ingest/types";
import { generateStructured, type StructuredMeta } from "../src/lib/llm/structured";
import { getModelName, getProvider } from "../src/lib/llm/provider";
import { createBrief } from "../src/lib/interview/brief";
import { buildReport } from "../src/lib/interview/report";
import type { InterviewState, Question } from "../src/lib/interview/schemas";
import { createInterviewState } from "../src/lib/interview/state";
import { runTurn, type TurnQuality } from "../src/lib/interview/turn";

const MAIN_QUESTIONS = 5;
type Candidate = "good" | "vague" | "wrong";
const CANDIDATES: Candidate[] = ["good", "vague", "wrong"];

const VAGUE_ANSWERS = [
  "It basically just works, I used it because everyone uses it and it is the best option.",
  "I followed a tutorial for that part, it handles everything automatically so I did not need to think about it much.",
  "That is handled by the framework, I think it is pretty scalable and secure in general.",
];
const WRONG_ANSWERS = [
  "It stores everything on the blockchain so it can never fail or lose data, which is why I did not add any error handling.",
  "The frontend talks directly to the database with SQL, so there is no backend or API involved at all.",
  "It uses machine learning to compile the code at runtime, so performance is not a concern at any scale.",
];

/** The "good" candidate: Gemma plays the student, with the relevant file in front of it. */
async function goodAnswer(source: RepoSource, state: InterviewState, question: Question): Promise<string> {
  const file = question.filesRead[0];
  const code = file ? (await source.readFile(file).catch(() => "")).slice(0, 4000) : "";
  const { value } = await generateStructured({
    instructions:
      "You are the student who built this project, answering in a technical interview. " +
      "Answer in 3 to 5 sentences. Be specific to this project, explain why, and mention one trade-off or alternative.",
    prompt: [
      `Project summary: ${state.brief.summary}`,
      `Stack: ${state.brief.stack.join(", ")}`,
      code ? `Relevant code from ${file}:\n${code}` : "",
      `Interviewer's question: ${question.text}`,
    ].join("\n\n"),
    schema: z.object({ answer: z.string().min(1) }),
    fallback: { answer: "" },
  });
  return value.answer;
}

type Sample = { fixture: string; candidate: Candidate; question: string; answer: string; followUp: string; quoteFound: boolean };

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

function percent(part: number, whole: number): string {
  return whole === 0 ? "n/a" : `${part}/${whole} (${Math.round((part / whole) * 100)}%)`;
}

async function main() {
  const requested = process.argv[2];
  const fixtures = (requested ? [requested] : [...FIXTURE_NAMES]) as FixtureName[];
  console.log(`provider=${getProvider()} model=${getModelName()} fixtures=${fixtures.join(",")} mainQuestions=${MAIN_QUESTIONS}`);

  mkdirSync("fixtures/briefs", { recursive: true });
  mkdirSync("fixtures/evals", { recursive: true });

  const metas: { kind: "brief" | "question" | "evaluation" | "report"; meta: StructuredMeta }[] = [];
  const qualities: TurnQuality[] = [];
  const samples: Sample[] = [];
  const scores: Record<Candidate, number[]> = { good: [], vague: [], wrong: [] };
  let briefInvented = 0;

  for (const name of fixtures) {
    const source = loadFixture(name);
    const briefResult = await createBrief(source);
    metas.push({ kind: "brief", meta: briefResult.meta });
    briefInvented += briefResult.inventedPathsDropped;
    writeFileSync(path.join("fixtures/briefs", `${name}.json`), JSON.stringify(briefResult.brief, null, 2));
    console.log(
      `\n[${name}] brief in ${briefResult.meta.ms} ms: ${briefResult.brief.hooks.length} hooks, ` +
        `${briefResult.inventedPathsDropped} invented paths dropped, fallback=${briefResult.meta.usedFallback}`,
    );

    for (const candidate of CANDIDATES) {
      let state = createInterviewState({
        repoId: source.id,
        repoLabel: source.label,
        filePaths: source.files.map((file) => file.path),
        brief: briefResult.brief,
        settings: { mainQuestions: MAIN_QUESTIONS, persona: "tough" },
      });
      const deps = { readFile: source.readFile };

      let turn = await runTurn(state, undefined, deps);
      let answerIndex = 0;
      while (turn.nextQuestion) {
        state = turn.state;
        const question = turn.nextQuestion;
        qualities.push(...turn.quality);
        for (const meta of turn.metas) metas.push({ kind: question.isFollowUp ? "evaluation" : "question", meta });

        const answer =
          candidate === "good"
            ? await goodAnswer(source, state, question)
            : (candidate === "vague" ? VAGUE_ANSWERS : WRONG_ANSWERS)[answerIndex++ % 3];

        turn = await runTurn(state, answer, deps);
        if (turn.evaluation?.evaluated) scores[candidate].push(turn.evaluation.score);
        if (turn.nextQuestion?.isFollowUp) {
          const grounded = turn.quality.find((q) => q.followUpReferencesAnswer !== null)?.followUpReferencesAnswer ?? false;
          samples.push({ fixture: name, candidate, question: question.text, answer, followUp: turn.nextQuestion.text, quoteFound: grounded });
        }
      }
      state = turn.state;
      qualities.push(...turn.quality);
      for (const meta of turn.metas) metas.push({ kind: "evaluation", meta });

      const { report, meta } = await buildReport(state);
      metas.push({ kind: "report", meta });
      console.log(
        `[${name}] ${candidate}: ${state.questions.length} questions (${state.questions.filter((q) => q.isFollowUp).length} follow-ups), ` +
          `overall ${report.overall}/4, ${report.readiness}`,
      );
    }
  }

  // ---- metrics ----
  const calls = metas.length;
  const fallbacks = metas.filter((m) => m.meta.usedFallback).length;
  const repairs = metas.filter((m) => m.meta.repaired).length;
  const deepDives = qualities.filter((q) => q.questionNamesRealFile !== null);
  const followUps = qualities.filter((q) => q.followUpReferencesAnswer !== null);
  const average = (values: number[]) => (values.length ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(2) : "n/a");

  const summary = {
    date: new Date().toISOString(),
    provider: getProvider(),
    model: getModelName(),
    fixtures,
    mainQuestions: MAIN_QUESTIONS,
    modelCalls: calls,
    validAfterRepair: percent(calls - fallbacks, calls),
    neededRepair: percent(repairs, calls),
    deepDiveNamesRealFile: percent(deepDives.filter((q) => q.questionNamesRealFile).length, deepDives.length),
    inventedPathsDropped: { inBriefs: briefInvented, inQuestions: qualities.filter((q) => q.inventedPathDropped).length },
    followUpQuoteFoundInAnswer: percent(followUps.filter((q) => q.followUpReferencesAnswer).length, followUps.length),
    averageScore: { good: average(scores.good), vague: average(scores.vague), wrong: average(scores.wrong) },
    medianMs: {
      brief: median(metas.filter((m) => m.kind === "brief").map((m) => m.meta.ms)),
      question: median(metas.filter((m) => m.kind === "question").map((m) => m.meta.ms)),
      evaluation: median(metas.filter((m) => m.kind === "evaluation").map((m) => m.meta.ms)),
      report: median(metas.filter((m) => m.kind === "report").map((m) => m.meta.ms)),
    },
    errors: [...new Set(metas.map((m) => m.meta.error).filter(Boolean))],
  };

  console.log("\n==== EVAL SUMMARY ====");
  console.log(JSON.stringify(summary, null, 2));
  writeFileSync("fixtures/evals/summary.json", JSON.stringify(summary, null, 2));
  // Follow-up samples for the manual grounding check (read 10 of them by hand).
  writeFileSync("fixtures/evals/followup-samples.json", JSON.stringify(samples, null, 2));
  console.log(`\nSaved fixtures/evals/summary.json and ${samples.length} follow-up samples.`);
}

main();

