/**
 * What the interviewer agent's tools need to know about the current request.
 *
 * The agent and its tools are created once. The repo being discussed changes per request,
 * so it travels in Mastra's RequestContext and the tools read it from there.
 */
import { RequestContext } from "@mastra/core/request-context";
import type { Persona, ProvenanceEntry } from "../lib/interview/schemas";

export type RepoContext = {
  /** Every real file path in the candidate's repo. Tools refuse anything else. */
  filePaths: string[];
  readFile: (path: string) => Promise<string>;
  provenance: ProvenanceEntry[];
  /** Files the agent opened during this call, in order. Filled in by the readFile tool. */
  filesRead: string[];
  /** Human-readable lines for the UI's status text ("reading src/auth.ts"). */
  activity: string[];
};

export type VivaContext = {
  repo: RepoContext;
  persona: Persona;
  targetRole: string;
};

export function createRepoContext(input: Pick<RepoContext, "filePaths" | "readFile"> & { provenance?: ProvenanceEntry[] }): RepoContext {
  return { filePaths: input.filePaths, readFile: input.readFile, provenance: input.provenance ?? [], filesRead: [], activity: [] };
}

export function createRequestContext(values: VivaContext): RequestContext<VivaContext> {
  const context = new RequestContext<VivaContext>();
  context.set("repo", values.repo);
  context.set("persona", values.persona);
  context.set("targetRole", values.targetRole);
  return context;
}

/**
 * The interviewer's tools for looking at the candidate's code mid-interview.
 *
 * Every path the model passes in is checked against the repo's real file list first.
 * A made-up path gets a clear error message back instead of file content.
 */
import { createTool } from "@mastra/core/tools";
import { z } from "zod";
import { normalizePath } from "../../lib/interview/brief";
import type { RepoContext } from "../context";

/** How much of one file a single readFile call may return. */
export const TOOL_FILE_CAP_CHARS = 4_000;
const MAX_LISTED_PATHS = 150;

/** Pulls the current repo out of the request context that Mastra hands to every tool call. */
function repoFrom(context: { requestContext?: { get: (key: string) => unknown } }): RepoContext {
  const repo = context.requestContext?.get("repo") as RepoContext | undefined;
  if (!repo) throw new Error("No repo in the request context.");
  return repo;
}

export const listFiles = createTool({
  id: "listFiles",
  description: "List file paths in the candidate's repository. Optionally only those inside one folder.",
  inputSchema: z.object({
    folder: z.string().optional().describe('Folder to list, for example "src/components". Leave out for the whole repo.'),
  }),
  outputSchema: z.object({ paths: z.array(z.string()), truncated: z.boolean() }),
  execute: async (input, context) => {
    const repo = repoFrom(context);
    const prefix = input.folder ? `${normalizePath(input.folder).replace(/\/$/, "")}/` : "";
    const paths = repo.filePaths.filter((path) => path.startsWith(prefix));
    repo.activity.push(prefix ? `listing ${prefix}` : "listing files");
    return { paths: paths.slice(0, MAX_LISTED_PATHS), truncated: paths.length > MAX_LISTED_PATHS };
  },
});

export const readFile = createTool({
  id: "readFile",
  description:
    "Read a file from the candidate's repository so you can ask about its actual code. " +
    "The path must be one of the real file paths. Optionally give a line range.",
  inputSchema: z.object({
    path: z.string().describe("Repo-relative file path, copied exactly from the list of real file paths."),
    startLine: z.number().int().min(1).optional(),
    endLine: z.number().int().min(1).optional(),
  }),
  outputSchema: z.object({
    found: z.boolean(),
    path: z.string(),
    content: z.string(),
    truncated: z.boolean(),
    error: z.string().optional(),
  }),
  execute: async (input, context) => {
    const repo = repoFrom(context);
    const path = normalizePath(input.path);
    if (!repo.filePaths.includes(path)) {
      // The model invented a path. Tell it so, and let it pick a real one.
      repo.activity.push(`refused ${path} (not a real file)`);
      return { found: false, path, content: "", truncated: false, error: "No such file. Use a path from the list of real file paths." };
    }
    try {
      const text = await repo.readFile(path);
      const lines = text.split("\n");
      const start = (input.startLine ?? 1) - 1;
      const end = input.endLine ?? lines.length;
      const slice = lines.slice(start, end).join("\n");
      repo.filesRead.push(path);
      repo.activity.push(`reading ${path}`);
      return { found: true, path, content: slice.slice(0, TOOL_FILE_CAP_CHARS), truncated: slice.length > TOOL_FILE_CAP_CHARS };
    } catch {
      return { found: false, path, content: "", truncated: false, error: "The file exists but could not be read." };
    }
  },
});

export const getProvenance = createTool({
  id: "getProvenance",
  description:
    "Find out whether a file was written by an AI coding agent, and from which prompt. " +
    "Use it before asking about a file, so you can say 'your session shows the agent wrote this'.",
  inputSchema: z.object({ path: z.string().describe("Repo-relative file path.") }),
  outputSchema: z.object({
    aiAuthored: z.boolean(),
    entries: z.array(z.object({ commit: z.string(), promptSummary: z.string() })),
  }),
  execute: async (input, context) => {
    const repo = repoFrom(context);
    const path = normalizePath(input.path);
    // Filled from Entire checkpoints in Phase 3; until then the list is empty and this answers "no".
    const entries = repo.provenance.filter((entry) => entry.path === path);
    repo.activity.push(`checking who wrote ${path}`);
    return { aiAuthored: entries.length > 0, entries: entries.map((e) => ({ commit: e.commit, promptSummary: e.promptSummary })) };
  },
});

/**
 * The interviewer: a Mastra agent with tools for reading the candidate's code.
 *
 * Its instructions depend on the persona chosen for the session, which arrives in the request context.
 * What to ask next and how to score are decided by the prompts and state machine in src/lib/interview;
 * the agent's own job is to look at real code (through the tools) and put the question into words.
 */
import { Agent } from "@mastra/core/agent";
import { interviewerInstructions } from "../../lib/interview/prompts";
import { PersonaSchema } from "../../lib/interview/schemas";
import { getModelConfig } from "../../lib/llm/provider";
import { getProvenance, listFiles, readFile } from "../tools/repo";

const TOOL_RULES = [
  "You have tools to look at the candidate's repository:",
  "- readFile(path): open a file. Do this before asking how a specific piece of code works, and base the question on what you read.",
  "- listFiles(folder?): see which files exist.",
  "- getProvenance(path): check whether an AI coding agent wrote the file, and from which prompt.",
  "Use at most two tool calls per question. Never ask about code you have not read.",
].join("\n");

export const interviewer = new Agent({
  id: "interviewer",
  name: "Viva interviewer",
  instructions: ({ requestContext }) => {
    const persona = PersonaSchema.catch("tough").parse(requestContext.get("persona"));
    const targetRole = String(requestContext.get("targetRole") ?? "Software engineer");
    return `${interviewerInstructions(persona, targetRole)}\n\n${TOOL_RULES}`;
  },
  // A function, so LLM_PROVIDER is read when a call is made rather than when this file is first loaded.
  model: () => getModelConfig(),
  tools: { readFile, listFiles, getProvenance },
});

/** The Mastra instance. Agents are registered here so tracing (Phase 7) sees every call they make. */
import { Mastra } from "@mastra/core";
import { interviewer } from "./agents/interviewer";

export const mastra = new Mastra({
  agents: { interviewer },
});

/**
 * Runs the interviewer agent for one structured answer (a question draft).
 * It has the same shape as the plain model call in src/lib/llm/structured.ts, so the turn logic
 * can use either one. The difference: here the model may call tools before it answers.
 */
import { getCallTimeoutMs, getProvider, providerOptions } from "../lib/llm/provider";
import { paceHostedCall } from "../lib/llm/pacing";
import type { GenerateFn } from "../lib/llm/structured";
import type { Persona } from "../lib/interview/schemas";
import { createRequestContext, type RepoContext } from "./context";
import { mastra } from "./index";

/** Tool calls, then the answer. Each step is one request to the model. */
const MAX_STEPS = 4;

export function interviewerGenerate(input: { repo: RepoContext; persona: Persona; targetRole: string }): GenerateFn {
  return async ({ prompt, schema, timeoutMs }) => {
    // A call with tools resends the prompt on every step, so budget for about two steps.
    const pacedMs = getProvider() === "hosted" ? await paceHostedCall(prompt.length * 2) : 0;

    const res = await mastra.getAgent("interviewer").generate(prompt, {
      requestContext: createRequestContext(input),
      providerOptions,
      maxSteps: MAX_STEPS,
      structuredOutput: { schema, jsonPromptInjection: true },
      // Tool steps add round trips, so the agent gets twice the time of a plain call.
      abortSignal: AbortSignal.timeout((timeoutMs ?? getCallTimeoutMs()) * 2),
    });

    const usage = res.usage as { inputTokens?: number; outputTokens?: number } | undefined;
    return { object: res.object, inputTokens: usage?.inputTokens, outputTokens: usage?.outputTokens, pacedMs };
  };
}

