/**
 * Cross-session memory of weak spots, kept with Mastra memory on a local LibSQL file.
 *
 * Only in local mode (LOCAL_MODE=true): the file lives on the candidate's own laptop.
 * In hosted mode every function here is a no-op, so the server keeps nothing about anyone.
 *
 * Storage shape: one Mastra thread per repo; the weak spots are that thread's metadata.
 * Plain code reads and writes them (not the model), so what is remembered is predictable.
 */
import { mkdirSync } from "node:fs";
import path from "node:path";
import { LibSQLStore } from "@mastra/libsql";
import { Memory } from "@mastra/memory";
import { z } from "zod";
import { WeakSpotSchema, type WeakSpot } from "../lib/interview/schemas";

export function memoryEnabled(): boolean {
  return process.env.LOCAL_MODE === "true";
}

/** Shown in the UI so a visitor knows why the hosted demo does not remember them. */
export function memoryStatus(): { enabled: boolean; label: string } {
  return memoryEnabled()
    ? { enabled: true, label: "Memory is on: weak spots are saved on this computer only." }
    : { enabled: false, label: "Memory is a local-mode feature. The hosted demo stores nothing about you." };
}

let memory: Memory | undefined;

function getMemory(): Memory {
  if (!memory) {
    // Absolute path: a relative "file:" URL resolves differently under Next.js than in a script.
    // The turbopackIgnore comment stops the bundler from tracing this runtime-only path at build time.
    const dbPath = path.resolve(/*turbopackIgnore: true*/ process.cwd(), process.env.MEMORY_DB_PATH ?? ".viva/memory.db");
    mkdirSync(path.dirname(dbPath), { recursive: true });
    memory = new Memory({ storage: new LibSQLStore({ id: "viva-memory", url: `file:${dbPath}` }) });
  }
  return memory;
}

/** Thread ids are kept simple: letters, digits, dashes. "github:owner/repo" becomes "viva-github-owner-repo". */
export function threadIdFor(repoId: string): string {
  return `viva-${repoId.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
}

/** Last session's weak spots for this repo. Empty when there are none, or in hosted mode. */
export async function recallWeakSpots(repoId: string): Promise<WeakSpot[]> {
  if (!memoryEnabled()) return [];
  const thread = await getMemory().getThreadById({ threadId: threadIdFor(repoId) });
  // Stored data is checked like any other input; anything unexpected reads as "no memory".
  return z.array(WeakSpotSchema).catch([]).parse(thread?.metadata?.weakSpots);
}

export async function saveWeakSpots(repoId: string, weakSpots: WeakSpot[]): Promise<boolean> {
  if (!memoryEnabled()) return false;
  const threadId = threadIdFor(repoId);
  const metadata = { repoId, weakSpots, savedAt: new Date().toISOString() };
  const existing = await getMemory().getThreadById({ threadId });
  if (existing) await getMemory().updateThread({ id: threadId, title: existing.title ?? repoId, metadata });
  else await getMemory().createThread({ threadId, resourceId: threadId, title: repoId, metadata });
  return true;
}

/** "Forget this project": removes everything remembered about one repo. */
export async function forgetProject(repoId: string): Promise<boolean> {
  if (!memoryEnabled()) return false;
  const threadId = threadIdFor(repoId);
  const existing = await getMemory().getThreadById({ threadId });
  if (existing) await getMemory().deleteThread(threadId);
  return Boolean(existing);
}

/** Builds what one interview turn needs (see TurnDeps) with the Mastra interviewer agent plugged in. */
import type { RepoSource } from "../lib/ingest/types";
import type { ProvenanceEntry, Settings } from "../lib/interview/schemas";
import type { TurnDeps } from "../lib/interview/turn";
import { createRepoContext } from "./context";
import { interviewerGenerate } from "./generate";

export function createAgentDeps(source: RepoSource, settings: Pick<Settings, "persona" | "targetRole">, provenance: ProvenanceEntry[] = []): TurnDeps {
  const repo = createRepoContext({ filePaths: source.files.map((file) => file.path), readFile: source.readFile, provenance });
  return {
    readFile: source.readFile,
    agent: {
      generate: interviewerGenerate({ repo, persona: settings.persona, targetRole: settings.targetRole }),
      // splice(0) empties the list and returns what was in it, so each question reports only its own activity.
      takeFilesRead: () => repo.filesRead.splice(0),
      takeActivity: () => repo.activity.splice(0),
    },
  };
}

// One-off patch: progress vs last session and the weak spots to remember.
const fs = require("fs");
const root = "C:/Users/Home/Desktop/open-source/Personal-viva/";
function patch(file, pairs) {
  let t = fs.readFileSync(root + file, "utf8").replace(/\r\n/g, "\n");
  for (const [a, b] of pairs) {
    if (!t.includes(a)) throw new Error(file + " missing: " + a.slice(0, 70));
    t = t.replace(a, () => b);
  }
  fs.writeFileSync(root + file, t);
}

patch("src/lib/interview/report.ts", [
  [
    `/** Used when the model fails twice: coaching text assembled from the evaluations themselves. */`,
    `/**
 * Progress on the topics retested from last session.
 * "before" is the score remembered from last time; "after" is the average of this session's
 * retest question and its follow-ups on that topic.
 */
export function progressVsLast(state: InterviewState): Report["progressVsLast"] {
  const progress: Report["progressVsLast"] = [];
  for (const retest of state.questions.filter((q) => q.round === "retest" && !q.isFollowUp && q.retestTopic)) {
    const scores = state.evaluations
      .filter((evaluation) => {
        const question = state.questions.find((q) => q.id === evaluation.questionId);
        return evaluation.evaluated && question !== undefined && mainQuestionOf(state, question).id === retest.id;
      })
      .map((evaluation) => evaluation.score);
    const before = state.previousWeakSpots.find((spot) => spot.topic === retest.retestTopic);
    if (scores.length === 0 || !before) continue;
    progress.push({ topic: before.topic, before: before.lastScore, after: averageScore(scores) });
  }
  return progress;
}

/** A retested topic counts as fixed once the candidate scores at least this on it. */
const FIXED_SCORE = 3;
const MAX_REMEMBERED = 5;

/**
 * What to remember for next time: retested topics that are still weak come first (so they are
 * retested again), then this session's new weak spots. No duplicates, at most five.
 */
export function weakSpotsToRemember(report: Report, sessionDate: string): WeakSpot[] {
  const stillWeak: WeakSpot[] = report.progressVsLast
    .filter((item) => item.after < FIXED_SCORE)
    .map((item) => ({ topic: item.topic, evidence: "Still weak when retested.", lastScore: item.after, sessionDate }));
  const retested = new Set(report.progressVsLast.map((item) => item.topic.toLowerCase()));
  const fresh = report.weakSpots.filter((spot) => !retested.has(spot.topic.toLowerCase()));
  return [...stillWeak, ...fresh].slice(0, MAX_REMEMBERED);
}

