/**
 * Turns raw Entire checkpoint data into an "AI-authored map": which files an AI agent wrote,
 * in which commit, and from which prompt.
 *
 * Pure functions only. The readers in local.ts and github.ts fetch the raw data; everything here
 * can be tested with plain objects.
 *
 * How Entire stores a checkpoint (verified on this repo, CLI 0.11.3, DECISIONS D18 to D22):
 *   - a git ref refs/entire/checkpoints/<shard>/<id> whose tree holds metadata.json,
 *     0/metadata.json, 0/prompt.txt and 0/transcript.jsonl
 *   - the code commit made during the session carries the trailer "Entire-Checkpoint: <id>"
 */
import type { ProvenanceEntry } from "../interview/schemas";

/** What we need from one checkpoint's metadata files. */
export type CheckpointInfo = {
  id: string;
  sessionId: string;
  /** ISO time the checkpoint was written. */
  createdAt: string;
  /** Files Entire saw the agent touch. Can be incomplete (see buildProvenance). */
  filesTouched: string[];
  agentLines: number;
  agentPercentage: number;
};

/** A normal code commit that is linked to a checkpoint by its trailer. */
export type LinkedCommit = { sha: string; checkpointId: string; files: string[] };

/** Something a person typed in the agent session. */
export type UserPrompt = { ts: string; text: string };

/** Everything buildProvenance needs. This is also the shape saved in fixtures/viva/checkpoints.json. */
export type ProvenanceInput = {
  checkpoints: CheckpointInfo[];
  commits: LinkedCommit[];
  /** Human prompts per session id, oldest first. */
  promptsBySession: Record<string, UserPrompt[]>;
};

const TRAILER = /^Entire-Checkpoint:\s*([0-9A-Za-z]+)\s*$/m;

/** Reads the checkpoint id from a commit message's trailer, or null if the commit is not linked. */
export function checkpointIdFromMessage(message: string): string | null {
  return message.match(TRAILER)?.[1] ?? null;
}

/** Tolerant JSON read of metadata.json and 0/metadata.json: missing fields become empty values. */
export function parseCheckpointInfo(id: string, rootJson: string | null, sessionJson: string | null): CheckpointInfo | null {
  try {
    const root = rootJson ? (JSON.parse(rootJson) as Record<string, unknown>) : {};
    const session = sessionJson ? (JSON.parse(sessionJson) as Record<string, unknown>) : {};
    const attribution = (session.initial_attribution ?? {}) as Record<string, unknown>;
    const files = (session.files_touched ?? root.files_touched ?? []) as unknown;
    return {
      id,
      sessionId: String(session.session_id ?? ""),
      createdAt: String(session.created_at ?? ""),
      filesTouched: Array.isArray(files) ? files.map(String) : [],
      agentLines: Number(attribution.agent_lines ?? 0) || 0,
      agentPercentage: Number(attribution.agent_percentage ?? 0) || 0,
    };
  } catch {
    return null;
  }
}

/**
 * Is this transcript message something the person actually typed?
 * Sessions also record machine-made "user" messages: background task notifications,
 * system reminders, interruption markers. Our first checkpoint's prompt.txt was one of those,
 * which is why prompts are taken from the transcript and filtered here.
 */
export function cleanPrompt(raw: string): string | null {
  // A pasted block is still the person's own prompt; drop only the wrapper tags.
  const text = raw.replace(/<\/?pasted_content[^>]*>/g, "").trim();
  if (text.length < 12) return null; // "continue", "yes", empty lines
  if (text.startsWith("<")) return null; // <task-notification>, <system-reminder>, <command-name> ...
  if (text.startsWith("[Request interrupted")) return null;
  return text;
}

/** Extracts the human prompts from Entire's compact transcript (one JSON object per line). */
export function parseUserPrompts(transcriptJsonl: string): UserPrompt[] {
  const prompts: UserPrompt[] = [];
  for (const line of transcriptJsonl.split("\n")) {
    // Cheap pre-check so the (large) assistant lines are never parsed.
    if (!line.includes('"type":"user"')) continue;
    try {
      const entry = JSON.parse(line) as { type?: string; ts?: string; content?: { text?: string }[] };
      if (entry.type !== "user") continue;
      const text = cleanPrompt((entry.content ?? []).map((part) => part.text ?? "").join("\n"));
      if (text) prompts.push({ ts: entry.ts ?? "", text });
    } catch {
      // A malformed line is skipped; the rest of the transcript is still useful.
    }
  }
  return prompts;
}

/** One line, at most 160 characters, safe to quote back to the candidate. */
export function summarizePrompt(text: string): string {
  const oneLine = text.replace(/\s+/g, " ").trim();
  return oneLine.length <= 160 ? oneLine : `${oneLine.slice(0, 157)}...`;
}

/**
 * The prompt that led to a checkpoint: the first thing the person typed after the previous
 * checkpoint (that is usually the task; later messages are steering). If they typed nothing
 * in that window, the most recent earlier prompt is used.
 */
export function pickPrompt(prompts: UserPrompt[], after: string, upTo: string): UserPrompt | undefined {
  const inWindow = prompts.filter((prompt) => prompt.ts > after && prompt.ts <= upTo);
  if (inWindow.length > 0) return inWindow[0];
  const earlier = prompts.filter((prompt) => prompt.ts <= upTo);
  return earlier[earlier.length - 1];
}

/**
 * Builds the AI-authored map.
 *
 * Which files count as AI-written for a linked commit:
 *   - If Entire's attribution says the agent wrote lines AND lists touched files, use those files.
 *   - Otherwise use every file changed in the commit ("commit-level"). On this repo Entire's own
 *     list was incomplete (it credited 0 agent lines to commits the agent wrote entirely), so the
 *     commit-level fallback is what usually applies.
 * Only paths that exist in the repo today and pass `isRelevant` are kept.
 */
export function buildProvenance(input: ProvenanceInput, filePaths: string[], isRelevant: (path: string) => boolean = () => true): ProvenanceEntry[] {
  const known = new Set(filePaths);
  const byId = new Map(input.checkpoints.map((checkpoint) => [checkpoint.id, checkpoint]));
  const entries: ProvenanceEntry[] = [];

  for (const commit of input.commits) {
    const checkpoint = byId.get(commit.checkpointId);
    if (!checkpoint) continue;

    // The window for "which prompt led to this" starts at the previous checkpoint of the same session.
    const earlier = input.checkpoints
      .filter((other) => other.sessionId === checkpoint.sessionId && other.createdAt < checkpoint.createdAt)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    const windowStart = earlier[earlier.length - 1]?.createdAt ?? "";
    const prompt = pickPrompt(input.promptsBySession[checkpoint.sessionId] ?? [], windowStart, checkpoint.createdAt);

    const attributed = checkpoint.agentLines > 0 && checkpoint.filesTouched.length > 0;
    const touched = new Set(checkpoint.filesTouched);
    const files = attributed ? commit.files.filter((file) => touched.has(file)) : commit.files;

    for (const path of files) {
      if (!known.has(path) || !isRelevant(path)) continue;
      entries.push({
        path,
        commit: commit.sha.slice(0, 7),
        checkpointId: checkpoint.id,
        promptSummary: prompt ? summarizePrompt(prompt.text) : "(the session's prompt could not be read)",
        scope: "file",
        source: attributed ? "attribution" : "commit",
      });
    }
  }
  return entries;
}

export type AiWrittenArea = { path: string; commit: string; checkpointId: string; promptSummary: string; source: "attribution" | "commit" };

/** One line per file for the "AI-written areas" panel. The first entry for a path wins (commits arrive newest first). */
export function aiWrittenAreas(provenance: ProvenanceEntry[]): AiWrittenArea[] {
  const seen = new Set<string>();
  const areas: AiWrittenArea[] = [];
  for (const entry of provenance) {
    if (seen.has(entry.path)) continue;
    seen.add(entry.path);
    areas.push({ path: entry.path, commit: entry.commit, checkpointId: entry.checkpointId, promptSummary: entry.promptSummary, source: entry.source ?? "commit" });
  }
  return areas;
}

/** Reads Entire checkpoints from a git repository on this machine, using plain git commands. */
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { checkpointIdFromMessage, parseCheckpointInfo, parseUserPrompts, type LinkedCommit, type ProvenanceInput } from "./parse";

const run = promisify(execFile);

/** Runs git in the given folder. Returns null instead of throwing (not a repo, missing object, ...). */
async function git(folder: string, args: string[]): Promise<string | null> {
  try {
    // Transcripts can be several megabytes, hence the large buffer.
    const { stdout } = await run("git", ["-C", folder, ...args], { maxBuffer: 64 * 1024 * 1024, windowsHide: true });
    return stdout;
  } catch {
    return null;
  }
}

export async function readLocalCheckpoints(folder: string): Promise<ProvenanceInput> {
  const empty: ProvenanceInput = { checkpoints: [], commits: [], promptsBySession: {} };

  const refs = (await git(folder, ["for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/"]))?.split("\n").filter(Boolean) ?? [];
  if (refs.length === 0) return empty;

  const checkpoints = [];
  const refById = new Map<string, string>();
  for (const ref of refs) {
    const id = ref.split("/").pop() ?? "";
    const info = parseCheckpointInfo(id, await git(folder, ["show", `${ref}:metadata.json`]), await git(folder, ["show", `${ref}:0/metadata.json`]));
    if (!info) continue;
    checkpoints.push(info);
    refById.set(id, ref);
  }

  // Every commit on every branch, with its full message, to find the "Entire-Checkpoint" trailers.
  // %x1f and %x1e are separator characters that cannot appear in a commit message.
  const log = (await git(folder, ["log", "--all", "--format=%H%x1f%B%x1e"])) ?? "";
  const commits: LinkedCommit[] = [];
  for (const record of log.split("\x1e")) {
    const [sha, message] = record.trim().split("\x1f");
    const checkpointId = message ? checkpointIdFromMessage(message) : null;
    if (!sha || !checkpointId) continue;
    const files = (await git(folder, ["diff-tree", "--root", "--no-commit-id", "--name-only", "-r", sha]))?.split("\n").filter(Boolean) ?? [];
    commits.push({ sha, checkpointId, files });
  }

  // Each checkpoint's transcript holds the whole session so far, so the newest checkpoint of a
  // session has every prompt. Read only that one per session.
  const promptsBySession: ProvenanceInput["promptsBySession"] = {};
  const newestFirst = [...checkpoints].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  for (const checkpoint of newestFirst) {
    if (promptsBySession[checkpoint.sessionId]) continue;
    const transcript = await git(folder, ["show", `${refById.get(checkpoint.id)}:0/transcript.jsonl`]);
    promptsBySession[checkpoint.sessionId] = transcript ? parseUserPrompts(transcript) : [];
  }

  return { checkpoints, commits, promptsBySession };
}

/**
 * Reads Entire checkpoints from a public GitHub repo through the REST API (hosted mode).
 * Checkpoint refs are not branches, but GitHub serves them like any other ref (DECISIONS D22).
 */
import { checkpointIdFromMessage, parseCheckpointInfo, parseUserPrompts, type LinkedCommit, type ProvenanceInput } from "./parse";

/** Limits that keep one ingest from using up the GitHub rate limit (60 requests/hour without a token). */
const MAX_CHECKPOINTS = 12;
const MAX_LINKED_COMMITS = 12;
/** A transcript larger than this is skipped; the prompt then reads "could not be read". */
const MAX_TRANSCRIPT_BYTES = 8 * 1024 * 1024;

async function api<T>(path: string): Promise<T | null> {
  const headers: Record<string, string> = { accept: "application/vnd.github+json" };
  if (process.env.GITHUB_TOKEN) headers.authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  try {
    const res = await fetch(`https://api.github.com${path}`, { headers, signal: AbortSignal.timeout(20_000) });
    return res.ok ? ((await res.json()) as T) : null;
  } catch {
    return null;
  }
}

type TreeEntry = { path: string; type: string; sha: string; size?: number };

async function readBlob(repo: string, sha: string): Promise<string | null> {
  const blob = await api<{ content: string; encoding: string }>(`/repos/${repo}/git/blobs/${sha}`);
  if (!blob || blob.encoding !== "base64") return null;
  return Buffer.from(blob.content, "base64").toString("utf8");
}

export async function readGitHubCheckpoints(owner: string, name: string): Promise<ProvenanceInput> {
  const repo = `${owner}/${name}`;
  const empty: ProvenanceInput = { checkpoints: [], commits: [], promptsBySession: {} };

  const refs = await api<{ ref: string; object: { sha: string } }[]>(`/repos/${repo}/git/matching-refs/entire/checkpoints`);
  if (!refs || refs.length === 0) return empty;

  // Checkpoint ids are ULIDs, which sort by time, so the last ones are the newest.
  const newest = [...refs].sort((a, b) => a.ref.localeCompare(b.ref, "en", { numeric: false })).sort((a, b) => idOf(a.ref).localeCompare(idOf(b.ref))).slice(-MAX_CHECKPOINTS);

  const checkpoints = [];
  const transcriptBlob = new Map<string, TreeEntry>();
  for (const ref of newest) {
    const id = idOf(ref.ref);
    const tree = await api<{ tree: TreeEntry[] }>(`/repos/${repo}/git/trees/${ref.object.sha}?recursive=1`);
    if (!tree) continue;
    const blobOf = (path: string) => tree.tree.find((entry) => entry.path === path && entry.type === "blob");
    const root = blobOf("metadata.json");
    const session = blobOf("0/metadata.json");
    const info = parseCheckpointInfo(id, root ? await readBlob(repo, root.sha) : null, session ? await readBlob(repo, session.sha) : null);
    if (!info) continue;
    checkpoints.push(info);
    const transcript = blobOf("0/transcript.jsonl");
    if (transcript) transcriptBlob.set(id, transcript);
  }

  // Recent commits on the default branch; the trailer in the message links a commit to its checkpoint.
  const recent = (await api<{ sha: string; commit: { message: string } }[]>(`/repos/${repo}/commits?per_page=100`)) ?? [];
  const commits: LinkedCommit[] = [];
  for (const commit of recent) {
    const checkpointId = checkpointIdFromMessage(commit.commit.message);
    if (!checkpointId || commits.length >= MAX_LINKED_COMMITS) continue;
    const detail = await api<{ files?: { filename: string }[] }>(`/repos/${repo}/commits/${commit.sha}`);
    commits.push({ sha: commit.sha, checkpointId, files: (detail?.files ?? []).map((file) => file.filename) });
  }

  // One transcript per session: the newest checkpoint's transcript contains the whole session.
  const promptsBySession: ProvenanceInput["promptsBySession"] = {};
  for (const checkpoint of [...checkpoints].sort((a, b) => b.createdAt.localeCompare(a.createdAt))) {
    if (promptsBySession[checkpoint.sessionId]) continue;
    const blob = transcriptBlob.get(checkpoint.id);
    const text = blob && (blob.size ?? 0) <= MAX_TRANSCRIPT_BYTES ? await readBlob(repo, blob.sha) : null;
    promptsBySession[checkpoint.sessionId] = text ? parseUserPrompts(text) : [];
  }

  return { checkpoints, commits, promptsBySession };
}

function idOf(ref: string): string {
  return ref.split("/").pop() ?? "";
}

/**
 * Provenance entry point: given a repo, find out which files an AI agent wrote (from Entire checkpoints).
 * Never throws. A repo without checkpoints, or any read error, gives an empty result plus a short hint.
 */
import { isSourceFile } from "../ingest/select";
import type { RepoSource } from "../ingest/types";
import type { Hook, ProjectBrief, ProvenanceEntry } from "../interview/schemas";
import { readGitHubCheckpoints } from "./github";
import { readLocalCheckpoints } from "./local";
import { aiWrittenAreas, buildProvenance, type ProvenanceInput } from "./parse";

export const NO_CHECKPOINTS_HINT =
  "No Entire checkpoints found in this repo, so Viva cannot tell which parts an AI agent wrote. " +
  "Record your coding sessions with Entire (entire.io) and Viva will ask about the AI-written code.";

export type ProvenanceResult = {
  provenance: ProvenanceEntry[];
  checkpointCount: number;
  /** A sentence for the UI when there is nothing to show; null when provenance was found. */
  hint: string | null;
};

export function provenanceFromInput(input: ProvenanceInput, filePaths: string[]): ProvenanceResult {
  // Only source files make interview questions; docs, configs and fixtures are left out.
  const provenance = buildProvenance(input, filePaths, isSourceFile);
  return { provenance, checkpointCount: input.checkpoints.length, hint: input.checkpoints.length === 0 ? NO_CHECKPOINTS_HINT : null };
}

export async function loadProvenance(source: RepoSource): Promise<ProvenanceResult> {
  const filePaths = source.files.map((file) => file.path);
  try {
    if (source.origin?.kind === "github") return provenanceFromInput(await readGitHubCheckpoints(source.origin.owner, source.origin.repo), filePaths);
    if (source.origin?.kind === "local") return provenanceFromInput(await readLocalCheckpoints(source.origin.folder), filePaths);
  } catch {
    // Fall through to the quiet "nothing found" result.
  }
  return { provenance: [], checkpointCount: 0, hint: NO_CHECKPOINTS_HINT };
}

/** How many AI-written files become interview hooks. One deep-dive question uses one hook. */
const MAX_AI_HOOKS = 3;

/**
 * Adds "ai-authored" hooks to the brief so the interviewer asks about AI-written code.
 * Files the brief already found interesting come first; then the rest in provenance order.
 */
export function addAiHooks(brief: ProjectBrief, provenance: ProvenanceEntry[]): ProjectBrief {
  const areas = aiWrittenAreas(provenance);
  if (areas.length === 0) return brief;

  const mentioned = new Set(brief.hooks.map((hook) => hook.file).filter(Boolean));
  const ranked = [...areas.filter((area) => mentioned.has(area.path)), ...areas.filter((area) => !mentioned.has(area.path))];

  const aiHooks: Hook[] = ranked.slice(0, MAX_AI_HOOKS).map((area, index) => ({
    id: `ai${index + 1}`,
    kind: "ai-authored",
    ref: `AI-written code in ${area.path}`,
    file: area.path,
    why: `An Entire checkpoint (${area.checkpointId}, commit ${area.commit}) shows an AI agent session produced this file. The session's prompt: "${area.promptSummary}"`,
  }));
  return { ...brief, hooks: [...brief.hooks, ...aiHooks] };
}

